return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Greek','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 09:24+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'el','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" αποθηκεύτηκε.','"%1$s" created. %2$d template updated.'=>'"%1$s" δημιουργήθηκε. %2$d πρότυπα ενημερώθηκαν.' . "\0" . '"%1$s" δημιουργήθηκε. %2$d πρότυπα ενημερώθηκαν.','"%s" created.'=>'"%s" δημιουργήθηκε.','"product" (replaces "article")'=>'"προϊόν" (αντικαθιστά "άρθρο")','%1$d chars — good length. %2$s'=>'%1$d χαρακτήρες — καλή διάρκεια. %2$s','%1$d chars — may be truncated in SERPs (aim for 140–160). %2$s'=>'%1$d χαρακτήρες — ενδέχεται να περικοπούν στα αποτελέσματα αναζήτησης (στόχος 140–160). %2$s','%1$d chars — too short (aim for 140–160). %2$s'=>'%1$d χαρακτήρες — πολύ σύντομο (στόχος 140–160). %2$s','%1$d internal, %2$d external.'=>'%1$d εσωτερικοί, %2$d εξωτερικοί.','%1$d of %2$d image(s) missing alt text.'=>'%1$d από %2$d εικόνες λείπει το εναλλακτικό κείμενο.','%d chars — good length.'=>'%d χαρακτήρες — καλή διάρκεια.','%d external link(s), no internal links. Add internal links to related content.'=>'%d εξωτερικοί σύνδεσμοι, κανένας εσωτερικός. Προσθέστε εσωτερικούς συνδέσμους σε σχετικό περιεχόμενο.','%d H1 tags found — a page should have exactly one H1.'=>'Βρέθηκαν %d ετικέτες H1 — μια σελίδα πρέπει να έχει ακριβώς μία H1.','%d image(s), all have alt text.'=>'%d εικόνες, όλες έχουν εναλλακτικό κείμενο.','%d language not yet linked'=>'%d γλώσσα δεν έχει ακόμη συσχετιστεί' . "\0" . '%d γλώσσες δεν έχουν ακόμη συσχετιστεί','%d link updated.'=>'%d σύνδεσμος ενημερώθηκε.' . "\0" . '%d σύνδεσμοι ενημερώθηκαν.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'Δεν ήταν δυνατή η αυτόματη διαγραφή %d αρχείων τοπικής γλώσσας (ΟΡΙΖΕΙΤΑΙ το DISALLOW_FILE_MODS). Διαγράψτε το χειροκίνητα μέσω του διακομιστή σας ή WP-CLI: wp language core uninstall <locale>.' . "\0" . 'Δεν ήταν δυνατή η αυτόματη διαγραφή %d αρχείων τοπικής γλώσσας (ΟΡΙΖΕΙΤΑΙ το DISALLOW_FILE_MODS). Διαγράψτε τα χειροκίνητα μέσω του διακομιστή σας ή WP-CLI: wp language core uninstall <locale>.','%d locale file removed.'=>'Το αρχείο τοπικής γλώσσας %d διαγράφηκε.' . "\0" . 'Τα αρχεία τοπικής γλώσσας %d διαγράφηκαν.','%d locale pack installed.'=>'%d πακέτο locale εγκατεστημένο.' . "\0" . '%d πακέτα locale εγκατεστημένα.','%d navigation reference updated.'=>'Ενημερώθηκε %d αναφορά πλοήγησης.' . "\0" . 'Ενημερώθηκαν %d αναφορές πλοήγησης.','%d part reference updated.'=>'Ενημερώθηκε %d αναφορά τμήματος.' . "\0" . 'Ενημερώθηκαν %d αναφορές τμήματος.','%d words — below recommended minimum of 300.'=>'%d λέξεις — κάτω από το προτεινόμενο ελάχιστο των 300.','%d words — very thin content. Consider expanding to at least 300 words.'=>'%d λέξεις — πολύ λεπτό περιεχόμενο. Σκεφτείτε να το επεκτείνετε σε τουλάχιστον 300 λέξεις.','%d words.'=>'%d λέξεις.','%s Archive'=>'%s Αρχείο','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'Το %s είναι ενεργό και ήδη παράγει JSON-LD Schema.org. Το Lingua Forge έχει απενεργοποιήσει την δική του έξοδο schema για να αποτρέψει συγκρουόμενα γραφήματα. Σε αντίθεση με το Open Graph — όπου το LF προσθέτει og:locale πάνω από την έξοδο ενός άλλου πρόσθετου — το schema δεν μπορεί να συμπληρωθεί καθαρά: διπλά ή επικαλυπτόμενα JSON-LD γραφήματα προκαλούν σφάλματα επικύρωσης. Απενεργοποιήστε την έξοδο schema στο ανιχνευμένο πρόσθετο αν θέλετε το LF να διαχειρίζεται τα δομημένα δεδομένα.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'Το %s είναι ενεργό και δημιουργεί το δικό του χάρτη ιστοτόπου. Αυτός ο χάρτης είναι ξεχωριστός από τον χάρτη του LF. Και οι δύο πρέπει να υποβληθούν στη Google Search Console: ο χάρτης ιστοτόπου του SEO plugin καταγράφει το περιεχόμενό σας· ο χάρτης του LF προσθέτει τις πολυγλωσσικές εναλλακτικές συνδέσεις. Ο χάρτης του LF ανακοινώνεται αυτόματα στο robots.txt.','(avg %.1f hits/block)'=>'(μέσος όρος %.1f επιτυχίες/μπλοκ)','(avg %.1f hits/entry)'=>'(μέσο όρο %.1f χτυπήματα/καταχώριση)','(disabled)'=>'(απενεργοποιημένο)','(no title) #%d'=>'(χωρίς τίτλο) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} δεν είχαν αντικαταστάσιους συνδέσμους — επανεξέταση για διερεύνηση)','.txt file(s) in the directory'=>'.txt αρχεία στον κατάλογο','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — δεν βρέθηκαν υποκεφαλίδες H2. Η προσθήκη H2 βελτιώνει τη δομή.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d τοπικοποιημένο(α) πρότυπο(α) από το θέμα &#8220;%2$s&#8221;» διατηρούνται στη βάση δεδομένων, αλλά είναι επί του παρόντος ανενεργά. Θα ενεργοποιηθούν ξανά αν ενεργοποιήσετε ξανά αυτό το θέμα. Για να μεταφέρετε τις μεταφράσεις σας στο νέο θέμα, αναγεννήστε τες μέσω <strong>Ρυθμίσεις → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> αυτόματοι διορθώσιμοι σύνδεσμοι','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> σύνδεσμοι που χρειάζονται χειροκίνητο έλεγχο','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> παρωχημένη διαδρομή(ες)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> πρόβλημα(τα) προτύπου','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Υπάρχει ένα φυσικό αρχείο robots.txt στη ρίζα του ιστότοπου. Το εικονικό robots.txt του WordPress — και το Sitemap: φίλτρο του LF — παρακάμπτονται. Ο χάρτης ιστοτόπου του LF δεν ανακοινώνεται στις μηχανές αναζήτησης.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Δέχεται μόνο συμπιεσμένα αρχεία .mo. Το όνομα αρχείου πρέπει να ακολουθεί το μοτίβο {textdomain}-{locale}.mo. Η μεταφόρτωση αρχείου με το ίδιο όνομα με υπάρχον θα το αντικαταστήσει.','Action'=>'Ενέργεια','Actions'=>'Ενέργειες','active'=>'ενεργό','Active Languages'=>'Ενεργές Γλώσσες','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Ενεργές γλώσσες: προσθέστε κάθε γλώσσα που θέλετε να υποστηρίξετε. Κάθε γλώσσα λαμβάνει ένα πρόθεμα URL ή υποτομέα και μια ετικέτα hreflang στην ενότητα &lt;head&gt; της σελίδας.','Active Provider'=>'Ενεργός Πάροχος','Add entry'=>'Προσθήκη καταχώρισης','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Προσθέστε οδηγίες για βελτίωση του προσχεδίου — π.χ. κάντε το πιο σύντομο, προσθέστε μια ενότητα συμπερασμάτων, χρησιμοποιήστε πιο επίσημο ύφος, συμπεριλάβετε ένα μπλοκ FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Προσθέστε οδηγίες για βελτίωση του προσχεδίου — π.χ. κάντε το πιο σύντομο, προσθέστε μια ενότητα συμπερασμάτων, χρησιμοποιήστε πιο επίσημο ύφος…','Add new entry'=>'Προσθήκη νέας καταχώρισης','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Προσθέστε έναν όρο ανά γραμμή. Απαιτούνται τόσο ο πηγή όσο και η μεταφρασμένη έκδοση. Το ζεύγος γλωσσών καθορίζει σε ποιες εργασίες μετάφρασης εφαρμόζεται ο περιορισμός.','Add Sitemap directive to robots.txt'=>'Προσθέστε την οδηγία Sitemap στο robots.txt','Add the following line to your robots.txt manually:'=>'Προσθέστε χειροκίνητα την παρακάτω γραμμή στο robots.txt σας:','Add WooCommerce product tags to Open Graph output'=>'Προσθέστε ετικέτες προϊόντων WooCommerce στην έξοδο Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Προσθέτει έναν σύνδεσμο στη σελίδα αρχικής ώστε οι επισκέπτες να μπορούν να περιηγούνται στη γλώσσα τους.','Administrators only (manage_options)'=>'Μόνο διαχειριστές (διαχείριση_επιλογών)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Μετά την αλλαγή της κύριας γλώσσας, εκκαθαρίστε τους permalinks (ενότητα παρακάτω) για να ενημερωθεί η δρομολόγηση URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Μετά την αλλαγή των ρυθμίσεων δομής URL (πρόθεμα διαδρομής ↔ υποτομέας), επισκεφθείτε πάντα τις Ρυθμίσεις → Μόνιμοι σύνδεσμοι και κάντε κλικ στην Αποθήκευση αλλαγών για να εκκαθαρίσετε τους κανόνες ανακατεύθυνσης.','AI analysis failed. Please try again.'=>'Αποτυχία ανάλυσης AI. Παρακαλώ δοκιμάστε ξανά.','AI Behaviour Preset'=>'Προκαθορισμένο AI Συμπεριφοράς','AI cache cleared. %d entry was removed.'=>'Η προσωρινή μνήμη ΤΝ διαγράφηκε. %d καταχώριση αφαιρέθηκε.' . "\0" . 'Η προσωρινή μνήμη ΤΝ διαγράφηκε. %d καταχωρίσεις αφαιρέθηκαν.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Cache: λίστα αποθηκευμένων απαντήσεων AI με αριθμούς χτυπημάτων. Εκκαθαρίστε ολόκληρη την cache ή τις καταχωρίσεις μιας ανάρτησης. Χρησιμοποιήστε το "Εκκαθάριση" πριν δοκιμάσετε μια αλλαγή μετάφρασης — τα αποθηκευμένα αποτελέσματα επιστρέφονται ακόμη και όταν αλλάζετε την προεπιλογή ή το μοντέλο AI μέχρι να εκδιωχθεί η καταχώριση της cache.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Οι λειτουργίες AI είναι προαιρετικές. Η δρομολόγηση γλωσσών, το hreflang, ο διακόπτης γλώσσας και το σύστημα ομάδας μετάφρασης λειτουργούν όλα χωρίς διαμορφωμένο πάροχο.','AI Limits & Security'=>'Όρια AI & Ασφάλεια','AI provider returned an empty response.'=>'Ο πάροχος AI επέστρεψε κενή απάντηση.','AI Recommendations'=>'Συστάσεις AI','AI returned an unexpected response format. Please try again.'=>'Η AI επέστρεψε μια απροσδόκητη μορφή απάντησης. Παρακαλώ δοκιμάστε ξανά.','AI Usage'=>'Χρήση AI','AI Usage & Cache'=>'Χρήση & Cache AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Στόχος 120–160 χαρακτήρες. Αφήστε κενό για χρήση της εναλλακτικής λύσης από το απόσπασμα.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Όλες οι μεγάλες μηχανές αναζήτησης — Google, Bing και Yandex — ανακαλύπτουν αυτόματα τον χάρτη ιστοτόπου μέσω της οδηγίας Sitemap: στο robots.txt. Δεν απαιτείται χειροκίνητη ενέργεια. Τα κουμπιά παρακάτω στέλνουν άμεση ειδοποίηση ώστε η μηχανή να ξαναανιχνεύσει τον χάρτη τώρα αντί να περιμένει τον επόμενο προγραμματισμένο έλεγχο robots.txt.','All time'=>'Όλο το χρόνο','All types'=>'Όλοι οι τύποι','Allow editors to lock individual blocks'=>'Επιτρέψτε στους επιμελητές να κλειδώνουν μεμονωμένα μπλοκ','Allow Gutenberg template-editing mode on post screens'=>'Επιτρέψτε τη λειτουργία επεξεργασίας προτύπων Gutenberg στις οθόνες δημοσιεύσεων','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Επίσης διαγραφή αναθέσεων γλωσσών, σχέσεων μετάφρασης, μετα-περιγραφών, γλωσσάριου και μνήμης μετάφρασης όταν το πρόσθετο απεγκαθίσταται','Also generate meta description'=>'Επίσης δημιουργήστε μετα-περιγραφή','Alternative (server-side):'=>'Εναλλακτικά (διακομιστής-πλευρά):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Πάντα εκπέμπετε μόνο og:locale και og:locale:alternate. Χρησιμοποιήστε όταν ένα άλλο πρόσθετο ή θέμα διαχειρίζεται το πλήρες σύνολο OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Πάντα εκπέμπετε το πλήρες σύνολο OG + Twitter Card ανεξάρτητα από άλλα πρόσθετα. Χρησιμοποιήστε μόνο αν κανένα άλλο πρόσθετο δεν παράγει ετικέτες OG.','An unknown error occurred.'=>'Παρουσιάστηκε άγνωστο σφάλμα.','Analysis'=>'Ανάλυση','Analysis request failed. Please try again.'=>'Αποτυχία αιτήματος ανάλυσης. Παρακαλώ δοκιμάστε ξανά.','Analyze'=>'Ανάλυση','Analyzing…'=>'Ανάλυση σε εξέλιξη…','and'=>'και','Anthropic (Claude)'=>'Ανθρώπινη (Κλαούντ)','any'=>'οποιαδήποτε','API calls saved by cache'=>'Κλήσεις API αποθηκευμένες από την cache','API Key'=>'Κλειδί API','API Keys'=>'Κλειδιά API','API Keys Tab'=>'Επικεφαλίδα API Keys','API Response Cache'=>'Cache Απαντήσεων API','Appends the following line to your existing robots.txt: %s'=>'Προσθέτει την παρακάτω γραμμή στο υπάρχον robots.txt σας: %s','Applied ✓'=>'Εφαρμόστηκε ✓','Apply failed — please try again.'=>'Η εφαρμογή απέτυχε — παρακαλώ δοκιμάστε ξανά.','Apply to Block'=>'Εφαρμογή στο μπλοκ','Apply to Editor'=>'Εφαρμογή στον Επεξεργαστή','Apply to Footnote'=>'Εφαρμογή στην υποσημείωση','Apply to Meta Description'=>'Εφαρμογή στη Μετα-περιγραφή','Apply translation'=>'Εφαρμογή μετάφρασης','Applying…'=>'Εφαρμόζεται…','Approximate size'=>'Περίπου μέγεθος','Archive'=>'Αρχείο','Archive: %s'=>'Αρχείο: %s','Article / WebPage'=>'Άρθρο / Ιστοσελίδα','Article / WebPage — all singular posts and pages'=>'Άρθρο / Ιστοσελίδα — όλα τα μεμονωμένα άρθρα και σελίδες','Authors and above (edit_published_posts)'=>'Συγγραφείς και άνω (επεξεργασία_δημοσιευμένων_αναρτήσεων)','Auto (recommended)'=>'Αυτόματο (συνιστάται)','Behavior'=>'Συμπεριφορά','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Συμπεριφορά: επιλέξτε την προεπιλογή AI (Literal, Balanced, Creative), προσθέστε καθολικές οδηγίες προτροπής, ενεργοποιήστε ή απενεργοποιήστε την αυτόματη μετάφραση μετά την αποθήκευση ανάρτησης και διαμορφώστε τη Μνήμη Μετάφρασης.','Block Content'=>'Περιεχόμενο μπλοκ','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Παρουσιάζει μια ευγενική ειδοποίηση όταν η τρέχουσα σελίδα εμφανίζεται στη γλώσσα πηγής της επειδή δεν υπάρχει μετάφραση για τη γλώσσα του επισκέπτη. Τροφοδοτείται από το σήμα LINGUAFORGE_LANG_FALLBACK_ACTIVE του δρομολογητή Lingua Forge — δεν εκπέμπει τίποτα όταν υπάρχει μετάφραση για τη ζητούμενη τοποθεσία.','Block Editor'=>'Επεξεργαστής Μπλοκ','block keywordfallback'=>'εναλλακτική','block keywordi18n'=>'i18n','block keywordlanguage'=>'γλώσσα','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'μετάφραση','Block locking'=>'Κλείδωμα μπλοκ','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Μοτίβα μπλοκ που έχουν καταχωρηθεί για προσαρμοσμένους τύπους ανάρτησης. Χρησιμοποιήστε το κουμπί Μετάφραση για να δημιουργήσετε μια παραλλαγή γλώσσας. Το μεταφρασμένο περιεχόμενο αποθηκεύεται εδώ και μπορεί να αντιγραφεί σε οποιαδήποτε ανάρτηση CPT από τον εισαγωγέα μοτίβων επεξεργαστή μπλοκ ή να χρησιμοποιηθεί ως σημείο εκκίνησης για ένα Συγχρονισμένο Μοτίβο (Επαναχρησιμοποιήσιμο Μπλοκ).','block titleMissing Translation Notice'=>'Ειδοποίηση απουσίας μετάφρασης','Block translation reuses'=>'Χρήση επαναχρησιμοποίησης μετάφρασης μπλοκ','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Μνήμη cache μετάφρασης επιπέδου μπλοκ που μοιράζεται μεταξύ αναρτήσεων. Όταν ενεργοποιείται, τα ίδια μπλοκ (ίδια μορφοποίηση, ζεύγος γλωσσών και γλωσσάρι) σερβίρονται από τη μνήμη αντί να καλούν ξανά το AI. Διαμορφώστε στις Ρυθμίσεις → Συμπεριφορά.','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Τα άρθρα ιστολογίου χρησιμοποιούν το Article· όλοι οι άλλοι τύποι δημοσιεύσεων και σελίδες χρησιμοποιούν WebPage. Περιλαμβάνει τίτλο, περιγραφή, inLanguage, url, datePublished, dateModified, εικόνα και εκδότη.','Browser language redirect'=>'Ανακατεύθυνση γλώσσας περιηγητή','Built-in preset instructions:'=>'Ενσωματωμένες προεπιλεγμένες οδηγίες:','Bulletize (•-prefixed)'=>'Καταγράψτε με κουκκίδες (•-προσημειωμένο)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Αποθηκεύει μεταφραστικά ισοδύναμα σε επίπεδο μπλοκ ώστε το επαναχρησιμοποιήσιμο περιεχόμενο (κοινά υποσέλιδα, πλαϊνές γραμμές, ακορντεόν, νομικές ενότητες με πολύ κείμενο) να μην κάνει κλήση API κάθε φορά. Όταν ενεργοποιείται, η ροή μετάφρασης αναλύει κάθε δημοσίευμα σε μπλοκ, ελέγχει κάθε μπλοκ στη μνήμη cache και στέλνει μόνο τα μη αποθηκευμένα μπλοκ στο AI σε μια ενιαία αίτηση. Οι επεξεργασίες γλωσσάρι και οι αλλαγές στην προεπιλογή Συμμόρφωσης ακυρώνουν αυτόματα τις επηρεαζόμενες αποθηκευμένες μεταφράσεις. Προβολή στατιστικών και διαγραφή της μνήμης cache στην ενότητα Συντήρηση.','cached'=>'αποθηκευμένο','Cached API responses'=>'Αποθηκευμένες απαντήσεις API','Cached block translations'=>'Αποθηκευμένες μεταφράσεις μπλοκ','Cancel'=>'Ακύρωση','Cannot determine target language from slug.'=>'Αδύνατη η προσδιορισμός της στόχου γλώσσας από το slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Δεν είναι δυνατή η εγγραφή στον προϊόν %1$d: είναι μεταφρασμένη έκδοση (γλώσσα: %2$s)%3$s. Τα λειτουργικά δεδομένα (τιμή, απόθεμα, SKU, διαστάσεις) πρέπει να ενημερώνονται στο αρχικό προϊόν. Εντοπίστε το ID του αρχικού προϊόντος μέσω: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Κανονική ετικέτα','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Περιορίστε τη χρήση AI που μπορεί να παράγει ο ιστότοπος και περιορίστε ποιοι ρόλοι χρηστών μπορούν να ενεργοποιήσουν πληρωμένες κλήσεις AI. Βρίσκεται πάνω από το όριο ρυθμού ανά χρήστη (30 αιτήματα / λεπτό, σκληρά κωδικοποιημένο) που ήδη προστατεύει από ανεξέλεγκτες επαναλήψεις χρήστη.','chars'=>'χαρακτήρες','Chunk translated'=>'Μπλοκ μεταφράστηκε','Chunk translated to:'=>'Μπλοκ μεταφράστηκε σε:','Clear'=>'Καθαρισμός','Clear All'=>'Καθαρισμός όλων','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Εκκαθάριση όλων των αποθηκευμένων αποτελεσμάτων ΤΝ; Οι μελλοντικά αιτήματα θα ενεργοποιούν νέες κλήσεις API μέχρι να ξαναχτιστεί η προσωρινή μνήμη.','Clear API Response Cache'=>'Εκκαθάριση Cache Απαντήσεων API','Clear Debug Files'=>'Διαγραφή αρχείων αποσφαλμάτωσης','Clear hints'=>'Καθαρισμός υποδείξεων','Clear input'=>'Καθαρισμός εισόδου','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Εκκαθάριση ολόκληρης της μνήμης μετάφρασης; Οι μελλοντικές μεταφράσεις θα ξαναχτίσουν την cache καθώς εκτελούνται.','Clear Translation Memory'=>'Εκκαθάριση μνήμης μετάφρασης','Close'=>'Κλείσιμο','Close language panel'=>'Κλείσιμο πάνελ γλώσσας','Close popover'=>'Κλείσιμο αναδυόμενου','Compatibility'=>'Συμβατότητα','Compliance Preset'=>'Προεπιλογή Συμμόρφωσης','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Διαμορφώστε έναν πάροχο AI στις Ρυθμίσεις → Κλειδιά API για ενεργοποίηση συστάσεων με AI.','Content generated'=>'Δημιουργήθηκε περιεχόμενο','Content Generator'=>'Παραγωγός Περιεχομένου','Content ready'=>'Το περιεχόμενο είναι έτοιμο','Contributors and above — default (edit_posts)'=>'Συνεισφέροντες και άνω — προεπιλογή (επεξεργασία_αναρτήσεων)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Ελέγξτε πόσο περιεχόμενο αποστέλλεται στην AI και πόσο μεγάλο μπορεί να είναι το απάντημα. Αφήστε ένα πεδίο κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή (εμφανίζεται ως υπόδειγμα). Αυξήστε αυτές τις τιμές αν μεγάλες σελίδες κόβονται, μειώστε τις για να μειώσετε το κόστος API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Ελέγχει τον προϋπολογισμό δείκτη και τα όρια εισόδου για τη λειτουργία Παραγωγέα Περιεχομένου ΤΝ. Αφήστε τα πεδία κενά για να χρησιμοποιήσετε τις ενσωματωμένες προεπιλογές.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Ελέγχει τι συμβαίνει όταν ένας διαχειριστής διαγράφει το πρόσθετο από τα Πρόσθετα → Εγκατεστημένα πρόσθετα → Διαγραφή. Οι ρυθμίσεις και οι cache AI διαγράφονται πάντα. Οι αναθέσεις γλωσσών και οι σχέσεις μετάφρασης διατηρούνται από προεπιλογή ώστε μια τυχαία απεγκατάσταση ή επανεγκατάσταση να συνεχίσει από εκεί που σταμάτησε.','Conversational'=>'Διαλογικό','Copied ✓'=>'Αντιγράφηκε ✓','Copy'=>'Αντιγραφή','Copy failed — please copy the URL manually.'=>'Αποτυχία αντιγραφής — παρακαλώ αντιγράψτε τη διεύθυνση URL χειροκίνητα.','Copy markup'=>'Αντιγραφή κώδικα','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Αντιγράψτε την τρέχουσα διεύθυνση URL στο πρόχειρο. Εμφανίζει μήνυμα "Ο σύνδεσμος αντιγράφηκε" με επιτυχία.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Αντιγράψτε το αποτέλεσμα και επικολλήστε το όπου χρειάζεται (π.χ. απευθείας στο πεδίο σημείωσης).','Copy to safe storage'=>'Αντιγραφή σε ασφαλή αποθήκευση','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'ενέργειες copy/native/auto JS: διαχειρίζεται από το social-share.js του LF','Could not add entry: source term and target term are required.'=>'Αδυναμία προσθήκης καταχώρισης: απαιτούνται όρος πηγής και όρος στόχου.','Could not copy the file. Check that the uploads folder is writable.'=>'Δεν ήταν δυνατή η αντιγραφή του αρχείου. Ελέγξτε αν ο φάκελος ανεβάσματος είναι εγγράψιμος.','Could not instantiate the provider.'=>'Δεν ήταν δυνατή η δημιουργία του παρόχου.','Could not save the file. Check that the uploads folder is writable.'=>'Δεν ήταν δυνατή η αποθήκευση του αρχείου. Ελέγξτε αν ο φάκελος ανεβάσματος είναι εγγράψιμος.','Could not save the glossary entry.'=>'Αδυναμία αποθήκευσης της καταχώρισης λεξικού.','Could not write to robots.txt. Check file permissions.'=>'Δεν ήταν δυνατή η εγγραφή στο robots.txt. Ελέγξτε τα δικαιώματα αρχείων.','CPT Block Patterns'=>'Μοτίβα μπλοκ CPT','Create'=>'Δημιουργία','Create missing'=>'Δημιουργία ελλείποντος','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Η δημιουργία μεταφράσεων για τον τύπο δημοσίευσης "%s" απαιτεί ενεργή ενσωμάτωση. Παρακαλώ βεβαιωθείτε ότι η απαιτούμενη ενσωμάτωση είναι εγκατεστημένη και ενεργή.','Creating…'=>'Δημιουργία…','Creative / Marketing'=>'Δημιουργικό / Μάρκετινγκ','Creative / Marketing instructions'=>'Δημιουργικές / Μάρκετινγκ οδηγίες','Current content (will be overwritten)'=>'Τρέχον περιεχόμενο (θα αντικατασταθεί)','Current status'=>'Τρέχουσα κατάσταση','Current title'=>'Τρέχων τίτλος','Current: {current}'=>'Τρέχον: {current}','Currently emitting'=>'Αυτή τη στιγμή εκπέμπεται','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Αυτή τη στιγμή κληρονομείται από τη σταθερά %s. Επιλέγοντας μια τιμή εδώ θα την αντικαταστήσει.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Αυτή τη στιγμή παραλείπεται για δημοσιεύματα που χρησιμοποιούν εικονίδια θέματος μπλοκ-comment (wp:details πεδία περίληψης, κ.λπ.) — αυτά περνούν στη υπάρχουσα διαδρομή μετάφρασης με μία κλήση.','Currently:'=>'Τρέχον: ','Custom'=>'Προσαρμοσμένο','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Η ημερήσια ποσόστωση AI έχει φτάσει (%1$d αιτήματα). Επαναφέρεται στις %2$s UTC.','Daily request limit'=>'Όριο ημερήσιων αιτημάτων','Danger Zone'=>'Ζώνη Κινδύνου','Debug Files'=>'Αρχεία αποσφαλμάτωσης','Debug files cleared. %d file was removed.'=>'Τα αρχεία αποσφαλμάτωσης διαγράφηκαν. %d αρχείο αφαιρέθηκε.' . "\0" . 'Τα αρχεία αποσφαλμάτωσης διαγράφηκαν. %d αρχεία αφαιρέθηκαν.','Debug logging'=>'Καταγραφή αποσφαλμάτωσης','Debug logging disabled.'=>'Η καταγραφή αποσφαλμάτωσης απενεργοποιήθηκε.','Debug logging enabled.'=>'Η καταγραφή αποσφαλμάτωσης ενεργοποιήθηκε.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Ανίχνευση σφαλμάτων: ενεργοποιήστε το αρχείο καταγραφής αποσφαλμάτωσης για να καταγράψετε τις προτροπές AI και τις απαντήσεις API σε τοπικό αρχείο. Απενεργοποιήστε μετά την αντιμετώπιση προβλημάτων — η λειτουργία αποσφαλμάτωσης γράφει ένα αρχείο σε κάθε αίτημα AI.','Default OG image'=>'Προεπιλεγμένη εικόνα OG','Delete'=>'Διαγραφή','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Διαγραφή όλων των αρχείων .txt στον κατάλογο αποσφαλμάτωσης; Ο ίδιος ο κατάλογος θα παραμείνει ώστε οι μελλοντικές εγγραφές αποσφαλμάτωσης να καταλήγουν καθαρές.','Delete all files for this override (both .mo and .po)?'=>'Διαγράψτε όλα τα αρχεία αυτής της παρακάμψεως (τόσο .mo όσο και .po);','Delete content data on uninstall'=>'Διαγραφή δεδομένων περιεχομένου κατά την απεγκατάσταση','Delete this glossary entry?'=>'Να διαγραφεί αυτή η καταχώριση λεξικού;','Describe what to write — topic, key points, structure…'=>'Περιγράψτε τι να γράψετε — θέμα, βασικά σημεία, δομή…','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Ανίχνευση ενεργών πρόσθετων SEO (Yoast, Rank Math, κ.λπ.) κατά την εκτέλεση. Εκπέμπει μόνο og:locale + og:locale:alternate όταν ένα άλλο πρόσθετο ήδη παράγει το πλήρες σετ OG. Εκπέμπει το πλήρες σετ όταν κανένα δεν ανιχνεύεται.','Directory'=>'Κατάλογος','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Απενεργοποίηση κατά τη διάρκεια ρύθμισης προτροπής ή όταν χρειάζεστε κάθε αίτημα να φτάσει στον πάροχο AI. Η απενεργοποίηση δεν διαγράφει τις αποθηκευμένες καταχωρίσεις — η επανενεργοποίησή τους τις επαναφέρει. Η άμεση αύξηση της δαπάνης API σε απασχολημένους ιστότοπους αναμένεται όταν είναι απενεργοποιημένο.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Απενεργοποίηση μόνο για ιστότοπους χωρίς κεφαλίδα ή πλήρως προσαρμοσμένες υλοποιήσεις hreflang. Όταν απενεργοποιείται, το LF δεν αφαιρεί πλέον το canonical tag του πυρήνα WordPress και δεν καταστέλλει πλέον την έξοδο hreflang του SEO plugin.','Disabled'=>'Απενεργοποιημένο','Disabled (by setting)'=>'Απενεργοποιημένο (με ρύθμιση)','Disabled (mode setting)'=>'Απενεργοποιημένο (ρύθμιση λειτουργίας)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Απενεργοποιημένο επειδή το μόνιμο πρόσθετο lf-social-share ήδη παρέχει αυτή τη λειτουργία.','DISALLOW_FILE_MODS is set.'=>'Το DISALLOW_FILE_MODS έχει οριστεί.','Display'=>'Εμφάνιση','Displays the Lingua Forge language switcher.'=>'Εμφανίζει τον διακόπτη γλώσσας Lingua Forge.','Do not output any OG tags.'=>'Μην παράγετε κανένα OG tag.','Documentation'=>'Τεκμηρίωση','Done'=>'Ολοκληρώθηκε','Done — {done} of {total} post(s) fixed.'=>'Ολοκληρώθηκε — διορθώθηκαν {done} από {total} αναρτήσεις.','Down'=>'Κάτω','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Κατεβάστε και εγκαταστήστε ένα πακέτο γλώσσας πυρήνα WordPress απευθείας από το WordPress.org. Μόλις εγκατασταθεί, η locale γίνεται διαθέσιμη για δρομολόγηση URL και τη ροή εργασίας μετάφρασης AI. Η λίστα των διαθέσιμων γλωσσών λαμβάνεται κατ\' απαίτηση — κάντε κλικ στο κουμπί παρακάτω για φόρτωση.','Dropdown direction'=>'Κατεύθυνση αναδυόμενου μενού','edit'=>'επεξεργασία','Editors and above (edit_others_posts)'=>'Επεξεργαστές και άνω (επεξεργασία_άλλων_αναρτήσεων)','Enable API response caching'=>'Ενεργοποίηση cache απαντήσεων API','Enable block-level translation cache reuse across posts'=>'Ενεργοποίηση επανάχρησης cache μεταφράσεων σε επίπεδο μπλοκ σε δημοσιεύματα','Enable Social Share URL rewriting for Social Icons blocks'=>'Ενεργοποίηση ανακατεύθυνσης URL κοινωνικής κοινής χρήσης για μπλοκ εικονιδίων κοινωνικής δικτύωσης','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Εισάγετε το κλειδί API για τουλάχιστον έναν πάροχο AI. Τα κλειδιά είναι κρυπτογραφημένα σε κατάσταση αναμονής χρησιμοποιώντας AES-256-GCM με ένα μυστικό συγκεκριμένο για τον ιστότοπο (LINGUAFORGE_SECRET). Μην μοιράζεστε εξαγωγές βάσεων δεδομένων χωρίς πρώτα να περιστρέψετε το μυστικό.','environment variable'=>'μεταβλητή περιβάλλοντος','Error'=>'Σφάλμα','Expand'=>'Επεκτείνετε','Expected: {expected}'=>'Αναμενόμενο: {expected}','External share services'=>'Εξωτερικές υπηρεσίες κοινής χρήσης','Extra guidance — tone, style, constraints, target audience…'=>'Επιπλέον καθοδήγηση — τόνος, στυλ, περιορισμοί, κοινό-στόχος…','Extra guidance — tone, style, constraints…'=>'Επιπλέον καθοδήγηση — τόνος, στυλ, περιορισμοί…','Failed. Please try again.'=>'Απέτυχε. Παρακαλώ δοκιμάστε ξανά.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL εφεδρικής εικόνας που χρησιμοποιείται όταν μια σελίδα δεν έχει επιλεγμένη εικόνα, λογότυπο ιστότοπου ή εικονίδιο ιστότοπου. Εμφανίζεται σε κοινωνικές προεπισκοπήσεις για αρχεία, τον δείκτη ιστολογίου και οποιαδήποτε μοναδική σελίδα χωρίς μικρογραφία.','Feature'=>'Λειτουργία','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Οι λειτουργίες ομαδοποιούνται σε δύο επίπεδα. Εισάγετε τον ακριβή αναγνωριστικό μοντέλου για κάθε επίπεδο και πάροχο. Αφήστε κενό ένα πεδίο για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή (εμφανίζεται ως υπόδειξη). Μόνο τα μοντέλα του ενεργού παρόχου καλούνται κατά την εκτέλεση — διαμορφώστε τα άλλα εκ των προτέρων αν σκοπεύετε να αλλάξετε.','File copied to safe storage successfully.'=>'Το αρχείο αντιγράφηκε με επιτυχία σε ασφαλή αποθήκευση.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Οι τροποποιήσεις αρχείων είναι απενεργοποιημένες (DISALLOW_FILE_MODS).','Files'=>'Αρχεία','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Τα αρχεία καταλήγουν στον παρακάτω κατάλογο. Χρησιμοποιείται για διάγνωση θεμάτων μετάφρασης — απενεργοποιήστε μόλις έχετε ό,τι χρειάζεστε ώστε τα αρχεία να μην συσσωρεύονται. Μπορείτε επίσης να το επιβάλετε από το wp-config.php με `define( \'LINGUAFORGE_AI_DEBUG\', true );` που υπερισχύει αυτής της εναλλαγής.','Filter'=>'Φίλτρο','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Φιλτράρισμα κατά γλώσσα και τύπο ανάρτησης, περιήγηση στο περιεχόμενό σας και κλικ στην Ανάλυση σε οποιοδήποτε στοιχείο για εκτέλεση ελέγχου SEO βάσει κανόνων — μήκος τίτλου, μετα-περιγραφή, αριθμός λέξεων, δομή επικεφαλίδων, κάλυψη εναλλακτικών εικόνων, και εσωτερικοί σύνδεσμοι.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Φίλτρο με το linguaforge_debug_dir για ανακατεύθυνση της εξόδου αποσφαλμάτωσης σε μη δημόσιο προορισμό.','Finding'=>'Εύρεση','Fix'=>'Διόρθωση','Fix All'=>'Διόρθωσε Όλα','Fix all links'=>'Επιδιόρθωση όλων των συνδέσμων','Fix all parts'=>'Επιδιόρθωση όλων των μερών','Fix Links'=>'Επιδιόρθωση Συνδέσμων','Fix Nav'=>'Επιδιόρθωση Πλοήγησης','Fix Parts'=>'Επιδιόρθωση Μερών','Fix Template'=>'Διόρθωση Προτύπου','Fixing {n} / {total}…'=>'Διόρθωση {n} / {total}…','Fixing…'=>'Επιδιόρθωση…','Flush Permalink Rules'=>'Καθαρισμός Κανόνων Permalink','Flush Permalinks'=>'Καθαρισμός Permalinks','Flush Sitemap Cache'=>'Εκκαθάριση cache sitemap','Footnote Content'=>'Περιεχόμενο υποσημείωσης','footnote(s) translated — applied together with content.'=>'Μεταφρασμένες σημειώσεις (footnote) — εφαρμόζονται μαζί με το περιεχόμενο.','Footnotes'=>'Σημειώσεις','Footnotes payload (advanced)'=>'Περιεχόμενο υποσημειώσεων (προχωρημένο)','Forbidden'=>'Απαγορεύεται','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Επιβολή ΑΠΕΝΕΡΓΟ από το σταθερό LINGUAFORGE_AI_DEBUG στο wp-config.php. Αφαιρέστε αυτήν τη γραμμή για να ελέγξετε αυτήν την εναλλαγή από εδώ.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Επιβολή ΕΝΕΡΓΟ από το σταθερό LINGUAFORGE_AI_DEBUG στο wp-config.php. Αφαιρέστε αυτήν τη γραμμή για να ελέγξετε αυτήν την εναλλαγή από εδώ.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Επιβάλλει την ανανέωση του sitemap στην επόμενη αίτηση. Χρησιμοποιήστε μετά την μαζική εισαγωγή ή χειροκίνητη επεξεργασία των σχέσεων μετάφρασης.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Βρέθηκαν {parts} σε <strong>{total}</strong> από <strong>{scanned}</strong> ανιχνευμένες αναρτήσεις για <strong>{lang}</strong>.','From'=>'Από','Front Page'=>'Αρχική Σελίδα','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Τοπική διαμόρφωση FSE: σκαλωσιά, μετάφραση και διόρθωση συνδέσμων σε πρότυπα και τμήματα προτύπων του Full Site Editing απευθείας από αυτήν την καρτέλα.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Τα πρότυπα FSE που έχουν δημιουργηθεί από το ενεργό θέμα. Δημιουργήστε και προσαρμόστε στο Επεξεργαστή Ιστοσελίδας.','Full'=>'Πλήρες','Full Article'=>'Ολόκληρο το άρθρο','Full post'=>'Πλήρες ποστ','General'=>'Γενικά','Generate'=>'Δημιουργία','Generate Content'=>'Παραγωγή περιεχομένου','Generate content…'=>'Δημιουργία περιεχομένου…','Generate Excerpt'=>'Δημιουργία αποσπάσματος','Generate Meta Description'=>'Δημιουργία μετα-περιγραφής','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Δημιουργία πολύγλωσσου sitemap στο /lf-sitemap.xml','Generated Content'=>'Παραγόμενο Περιεχόμενο','Generated meta description'=>'Παραγόμενη μετα-περιγραφή','Generating…'=>'Παραγωγή…','Generation failed.'=>'Η δημιουργία απέτυχε.','Getting started'=>'Εκκίνηση','Global AI preset'=>'Παγκόσμια προεπιλογή AI','Global default (%s)'=>'Παγκόσμια προεπιλογή (%s)','Glossary'=>'Γλωσσάρι','Glossary entry added.'=>'Καταχώριση λεξικού προστέθηκε.','Glossary entry removed.'=>'Καταχώριση λεξικού αφαιρέθηκε.','Glossary Tab'=>'Γλωσσάρι','Google (Gemini)'=>'Google (Gemini)','Headings'=>'Επικεφαλίδες','Hide'=>'Απόκρυψη','Hints'=>'Υποδείξεις','Home link text'=>'Κείμενο συνδέσμου αρχικής','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Πώς πρέπει να εμφανίζεται στη μετάφραση. Πληκτρολογήστε την ίδια τιμή με τον όρο πηγής για να την διατηρήσετε αυτούσια.','How to use'=>'Πώς να χρησιμοποιήσετε','Hreflang'=>'Hreflang','Hreflang output'=>'Έξοδος hreflang','Hreflang settings saved.'=>'Οι ρυθμίσεις hreflang αποθηκεύτηκαν.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Εικονίδιο + ετικέτα','Icon only'=>'Μόνο εικονίδιο','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Εάν επιλεγεί, η απεγκατάσταση του πρόσθετου θα διαγράψει οριστικά όλες τις αναθέσεις γλωσσών, σχέσεις μετάφρασης, μετα-περιγραφές, προεπιλογές σελίδων, το γλωσσάρι AI και τη μνήμη μετάφρασης για κάθε ανάρτηση σε αυτόν τον ιστότοπο. Αυτό δεν μπορεί να αναιρεθεί. Αφήστε το ανεπιλεγμένο εκτός αν αφαιρείτε πλήρως την πολύγλωσση υποστήριξη από τον ιστότοπο.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Εάν έχετε εγκαταστήσει ένα γενικό πρόσθετο SEO, αυτό το πάνελ δείχνει πώς το LF προσαρμόζεται για να αποφύγει διπλή έξοδο. Ο στόχος είναι η αποφυγή συγκρούσεων — όχι η συνεργασία. Το LF παρέχει πάντα το πολύγλωσσο επίπεδο SEO (hreflang, og:locale, inLanguage schema) που απαιτεί γνώση της διαμόρφωσης δρομολόγησης γλώσσας του LF για σωστή παραγωγή.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Εάν έχετε εγκαταστήσει Yoast SEO, Rank Math, All in One SEO ή SEOPress, το Lingua Forge τα ανιχνεύει και προσαρμόζεται για να αποφύγει διπλή έξοδο. Για το hreflang, το LF αναλαμβάνει πλήρως και καταστέλλει την έξοδο του πρόσθετου επειδή αυτά τα πρόσθετα δεν μπορούν να παράγουν σωστό hreflang για μια πολύγλωσση διαμόρφωση δρομολόγησης. Για το Open Graph, το LF προσθέτει μόνο og:locale και og:locale:alternate — τα πολύγλωσσα σήματα που το πρόσθετο δεν μπορεί να παράγει — και αφήνει το βασικό σετ OG στο πρόσθετο. Για το Schema.org, το LF απενεργοποιεί εντελώς τη δική του έξοδο για να αποφύγει συγκρουόμενα γραφήματα JSON-LD.','Images'=>'Εικόνες','Improve writing'=>'Βελτίωση γραφής','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Στον επεξεργαστή μπλοκ, προσθέστε ένα μπλοκ Εικονιδίων Κοινωνικής Δικτύωσης. Για κάθε εικονίδιο, ανοίξτε τις ρυθμίσεις συνδέσμου και εισάγετε μία από τις τιμές "share:" παρακάτω ως το URL. Στην εμπρόσθια όψη, το LF το αντικαθιστά με το σωστό URL κοινής χρήσης για την τρέχουσα σελίδα.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Περιλαμβάνει όνομα, περιγραφή, inLanguage, url, εικόνα και μια Προσφορά με τιμή, νόμισμα τιμής και διαθεσιμότητα. Η τιμή και η διαθεσιμότητα προέρχονται από το προϊόν της πηγής (μοντέλο κοινόχρηστου αποθέματος).','Includes site name, url, and inLanguage.'=>'Περιλαμβάνει όνομα ιστότοπου, url και inLanguage.','Informative'=>'Ενημερωτικό','Input tokens'=>'Εισαγωγικά tokens','Install'=>'Εγκατάσταση','Install a Language'=>'Εγκατάσταση Γλώσσας','Installed SEO plugins'=>'Εγκατεστημένα πρόσθετα SEO','Installing…'=>'Εγκατάσταση…','instock / oos / pending from WC stock status'=>'σε απόθεμα / εκτός αποθέματος / σε αναμονή από την κατάσταση αποθέματος του WC','Instructions (optional)'=>'Οδηγίες (προαιρετικά)','Instructions / key points'=>'Οδηγίες / βασικά σημεία','Integration API'=>'API Ενσωμάτωσης','Internal Link Fixer'=>'Εργαλείο Διόρθωσης Εσωτερικών Συνδέσμων','Introduction only'=>'Μόνο εισαγωγή','Invalid file reference.'=>'Μη έγκυρη αναφορά αρχείου.','Invalid filename.'=>'Μη έγκυρο όνομα αρχείου.','Invalid language code.'=>'Μη έγκυρος κωδικός γλώσσας.','Invalid language.'=>'Μη έγκυρη γλώσσα.','Invalid locale code.'=>'Μη έγκυρος κωδικός locale.','Invalid or primary language.'=>'Μη έγκυρη ή κύρια γλώσσα.','Invalid post ID.'=>'Μη έγκυρο ID ανάρτησης.','Invalid post type.'=>'Μη έγκυρος τύπος ανάρτησης.','Invalid template part.'=>'Μη έγκυρο τμήμα προτύπου.','Invalid template type.'=>'Μη έγκυρος τύπος προτύπου.','JavaScript-powered actions'=>'Ενέργειες με JavaScript','Key points, ideas, or structure to build from…'=>'Βασικά σημεία, ιδέες ή δομή από την οποία να χτιστεί…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Τα κλειδιά είναι κρυπτογραφημένα με AES-256-CBC πριν αποθηκευτούν στη βάση δεδομένων του WordPress. Το μυστικό κρυπτογράφησης προέρχεται από τα salts αυθεντικοποίησης του WordPress (wp-config.php), έτσι τα κείμενα σε απλό κείμενο ποτέ δεν έρχονται σε επαφή με τη βάση δεδομένων.','Language'=>'Γλώσσα','Language %s installed successfully.'=>'Η γλώσσα %s εγκαταστάθηκε με επιτυχία.','Language (optional)'=>'Γλώσσα (προαιρετικά)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Η εγκατάσταση γλώσσας είναι απενεργοποιημένη σε αυτόν τον διακομιστή (ορίζεται το DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Η εγκατάσταση γλώσσας είναι απενεργοποιημένη σε αυτόν τον διακομιστή. Η σταθερά DISALLOW_FILE_MODS ορίζεται στο wp-config.php. Εγκαταστήστε χειροκίνητα πακέτα γλώσσας μέσω WP-CLI: wp language core install de_DE','Language label'=>'Ετικέτα γλώσσας','Language Overrides'=>'Παρακάμψεις Γλώσσας','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Παρεμβολές γλώσσας: διαχειριστείτε αρχεία υπεροχής .po/.mo για τις συμβολοσειρές UI του Lingua Forge. Χρησιμοποιήστε αυτό αντί να επεξεργάζεστε απευθείας αρχεία πρόσθετου — οι υπεροχές παραμένουν μετά τις ενημερώσεις.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Η εγκατάσταση πακέτου γλώσσας απέτυχε. Η γλώσσα μπορεί ήδη να είναι εγκατεστημένη, ο κωδικός locale μπορεί να είναι λανθασμένος ή ο διακομιστής σας να εμποδίζει την εγγραφή αρχείων.','Language Setup'=>'Ρύθμιση Γλώσσας','Language Switcher'=>'Εναλλαγή Γλώσσας','Language switcher'=>'Διακόπτης γλώσσας','Language uninstalled. %d post deleted.'=>'Η γλώσσα απεγκαταστάθηκε. %d ανάρτηση διαγράφηκε.' . "\0" . 'Η γλώσσα απεγκαταστάθηκε. %d αναρτήσεις διαγράφηκαν.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Αντίγραφα συγκεκριμένων γλωσσών των μερών προτύπων του θέματος. Μόλις δημιουργηθούν, τα πρότυπα ενημερώνονται ώστε να αναφέρονται στο μέρος που είναι συγκεκριμένο για τη γλώσσα.','Language:'=>'Γλώσσα:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Οι γλώσσες που είναι γνωστές στον δρομολογητή (προερχόμενες από τα εγκατεστημένα πακέτα locale του WordPress συν την κύρια γλώσσα). Εγκαταστήστε πρόσθετα πακέτα γλώσσας στην παρακάτω ενότητα για να κάνετε περισσότερες γλώσσες διαθέσιμες για δρομολόγηση και μετάφραση.','Last 30 days'=>'Τελευταία 30 ημέρες','Last 7 days'=>'Τελευταία 7 ημέρες','Last generated: %s'=>'Τελευταία γεννήθηκε: %s','Lead paragraph (≤60 w)'=>'Εισαγωγική παράγραφος (≤60 λέξεις)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Αφήστε ένα πεδίο μοντέλου κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή για αυτό το επίπεδο. Το κείμενο υπόδειξης δείχνει ποιο μοντέλο θα χρησιμοποιηθεί.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Αφήστε κενό για ονόματα εμπορικών σημάτων και όρους που δεν σχετίζονται με γλώσσα και πρέπει να επιβάλλονται ανεξάρτητα από τη γλώσσα μεταφράσης.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Αφήστε κενό για να εφαρμοστεί σε όλες τις στοχευόμενες γλώσσες — ιδανικό για ονόματα εμπορικών σημάτων, συντομογραφίες και όρους που πρέπει να διατηρούνται αυτούσιοι σε κάθε μετάφραση.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Αφήστε κενό για να διατηρήσετε το υπάρχον κλειδί. Εισάγετε μια νέα τιμή για να το αντικαταστήσετε.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Αφήστε κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή. Η διαγραφή μιας αποθηκευμένης υπεροχής επαναφέρει την προεπιλογή στην επόμενη αποθήκευση.','Legacy lf-social-share mu-plugin'=>'Παλιό μόνιμο πρόσθετο lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Εντοπίστηκε παλιό μόνιμο πρόσθετο lf-social-share. Το LF αναβάλλει το βασικό σετ OG στο μόνιμο πρόσθετο και παράγει μόνο og:locale + og:locale:alternate. Μπορείτε να απενεργοποιήσετε το μόνιμο πρόσθετο — το ενσωματωμένο Κοινωνικό Μοιρασμό του LF (Επισκόπηση SEO → Κοινωνικός Μοιρασμός) και το Open Graph καλύπτουν την ίδια λειτουργικότητα.','Legal / Compliance'=>'Νομικό / Συμμόρφωση','Legal / Compliance instructions'=>'Νομικές / Συμμόρφωση οδηγίες','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'Το LF προσθέτει πάντα og:locale και og:locale:alternate — τα πολύγλωσσα σήματα που κανένα γενικό SEO plugin δεν μπορεί να παράγει σωστά. Για το βασικό σετ OG (og:title, og:description, og:image), το LF το παράγει όταν κανένα άλλο πρόσθετο δεν είναι παρόν. Όταν είναι εγκατεστημένο ένα SEO πρόσθετο, το LF παραλείπει το βασικό σετ για να αποφύγει διπλές ετικέτες — όχι επειδή το πρόσθετο είναι "καλύτερο", αλλά επειδή η διπλοτυπία δεν προσφέρει αξία.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'Το LF δημιουργεί το δικό του sitemap με εναλλακτικά xhtml:link για όλες τις ομάδες μεταφράσεων. Όταν είναι εγκατεστημένο ένα SEO πρόσθετο, δημιουργεί ένα ξεχωριστό sitemap — και τα δύο συνυπάρχουν ανεξάρτητα. Υποβάλετε και τα δύο στη Google Search Console: το sitemap του SEO plugin για ανακάλυψη περιεχομένου, το sitemap του LF για σήματα σχέσεων γλώσσας.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'Το LF παράγει ετικέτες hreflang και έχει αφαιρέσει το canonical tag του πυρήνα WordPress σε πολύγλωσσες σελίδες.','LF is suppressing hreflang output from: %s'=>'Το LF καταστέλλει την έξοδο hreflang από: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'Η LF παράγει ακριβείς hreflang για κάθε διαμορφωμένη γλώσσα, συμπεριλαμβανομένου του x-default. Τα γενικά πρόσθετα SEO δεν έχουν πρόσβαση στη διαμόρφωση δρομολόγησης LF και θα παρήγαγαν hreflang βάσει λανθασμένων υποθέσεων URL. Η LF καταστέλλει την έξοδό τους μέσω φίλτρου για να αποτρέψει συγκρούσεις.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'Η LF παράγει πολύγλωσσο JSON-LD με επισημάνσεις inLanguage συνδεδεμένες με τη διαμόρφωση δρομολόγησης γλώσσας. Όταν εγκαθίσταται ένα πρόσθετο SEO, η LF απενεργοποιεί εντελώς το δικό της σχήμα: τα διπλά γραφήματα JSON-LD παράγουν σφάλματα επικύρωσης και δεν υπάρχει καθαρός τρόπος να συμπληρώσετε ένα υπάρχον γράφημα.','LF provides'=>'Η LF παρέχει','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'Η LF αφαιρεί την ετικέτα canonical του πυρήνα WordPress σε πολύγλωσσες σελίδες επειδή οι κανόνες επαναγραφής με πρόθεμα γλώσσας του δρομολογητή και το hreflang x-default είναι τα σωστά κανόνα canonical για μια πολύγλωσση ιστοσελίδα. Αυτό αποτρέπει μια διπλή canonical εάν ένα πρόσθετο SEO επίσης παράγει ένα. Η LF δεν προσθέτει το δικό της canonical — η δρομολόγηση γλώσσας ήδη καθιστά κάθε URL canonical.','Light'=>'Ελαφρύ','Light (default — fast and cost-effective)'=>'Ελαφρύ (προεπιλογή — γρήγορο και οικονομικό)','Light (fast and cost-effective — Haiku / Flash)'=>'Ελαφρύ (γρήγορο και οικονομικό — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Φωτεινό: χρησιμοποιείται για μετα-περιγραφές και δημιουργία αποσπασμάτων — γρήγορο, χαμηλό κόστος.','Limit results to pages in the given Lingua Forge language code.'=>'Περιορίστε τα αποτελέσματα σε σελίδες με τον κωδικό γλώσσας Lingua Forge που δίνεται.','Limits'=>'Όρια','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Το Lingua Forge προσθέτει πολύγλωσση δρομολόγηση, μετάφραση με AI, ετικέτες SEO hreflang και διακόπτη γλώσσας στον ιστότοπό σας WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Η Lingua Forge προσθέτει ιδιότητες Open Graph ειδικές για WooCommerce στις σελίδες προϊόντων ώστε η κοινή χρήση ενός URL προϊόντος στο Facebook, Pinterest και παρόμοιες πλατφόρμες να εμφανίζει τον σωστό τύπο προϊόντος, τιμή και διαθεσιμότητα.','Lingua Forge AI Tools'=>'Εργαλεία Τεχνητής Νοημοσύνης Lingua Forge','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Η Lingua Forge επεκτείνει το μπλοκ Κοινωνικών Εικονιδίων του WordPress Core με δυναμικούς URLs κοινής χρήσης. Ορίστε οποιονδήποτε σύνδεσμο εικονιδίου σε τιμή "share:" και η LF το ξαναγράφει στον σωστό σύνδεσμο κοινής χρήσης ή ενέργεια JavaScript κατά την απόδοση — χωρίς ανάγκη για προσαρμοσμένο κώδικα ή πρόσθετο τρίτου μέρους.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Η Lingua Forge δημιουργεί ένα αποκλειστικό XML sitemap στη διεύθυνση /lf-sitemap.xml που προσθέτει εναλλακτικούς συνδέσμους γλώσσας για όλο το μεταφρασμένο περιεχόμενό σας. Αυτό το sitemap συμπληρώνει το sitemap του πυρήνα WordPress και οποιοδήποτε sitemap πρόσθετου SEO — δεν το αντικαθιστά.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Η Lingua Forge είναι μια ολοκληρωμένη λύση SEO για πολλαπλές γλώσσες. Δεν απαιτείται επιπλέον πρόσθετο SEO.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Η Lingua Forge είναι μια ολοκληρωμένη λύση SEO για πολλαπλές γλώσσες. Δεν απαιτείται πρόσθετο SEO ή sitemap.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Η Lingua Forge παράγει ετικέτες <link rel="alternate" hreflang> για κάθε διαμορφωμένη γλώσσα σε κάθε σελίδα, συμπεριλαμβανομένου του x-default που δείχνει στη γλώσσα πηγής. Αυτό είναι το κύριο σήμα πολ multilingual SEO για την Google και άλλες μηχανές αναζήτησης — δεν απαιτείται πρόσθετο plugin SEO.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Η Lingua Forge παράγει μετα-ετικέτες Open Graph και Twitter Card ώστε οι κοινόχρηστοι URLs να εμφανίζουν τη σωστή γλώσσα, τίτλο, περιγραφή και εικόνα σε κοινωνικές πλατφόρμες.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Η Lingua Forge παράγει δομημένα δεδομένα Schema.org JSON-LD ώστε οι μηχανές αναζήτησης να κατανοούν τον τύπο περιεχομένου, τη γλώσσα και τα μεταδεδομένα σας. Αυτός είναι ο κύριος τρόπος επικοινωνίας των annotations inLanguage για πολύγλωσσο περιεχόμενο προς την Google και άλλους crawlers.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Το Lingua Forge περιορίζει δύο λειτουργίες του Gutenberg από προεπιλογή για να διατηρεί συνεπή τη συμπεριφορά της επιμέλειας σε όλες τις γλώσσες. Επιλέξτε εδώ όταν χρειάζεστε πλήρεις δυνατότητες Gutenberg / FSE.','Lingua Forge Settings'=>'Ρυθμίσεις Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Το Lingua Forge χρησιμοποιεί δύο ανεξάρτητα επίπεδα cache για να αποφύγει περιττές κλήσεις API AI. Χρησιμοποιήστε τις καρτέλες παρακάτω για να επιθεωρήσετε και να διαχειριστείτε κάθε ένα.','Lingua Forge uses two model tiers per provider:'=>'Το Lingua Forge χρησιμοποιεί δύο επίπεδα μοντέλων ανά πάροχο:','Lingua Forge — Quick Translate'=>'Lingua Forge — Γρήγορη Μετάφραση','Lingua Forge — Settings'=>'Lingua Forge — Ρυθμίσεις','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Τα ενσωματωμένα modules Κοινωνικής Κοινής Χρήσης και Open Graph της Lingua Forge καλύπτουν όλη τη λειτουργικότητα που παρέχει το mu-plugin, plus υποστήριξη πολύγλωσσου og:locale. Μπορείτε με ασφάλεια να απενεργοποιήσετε το mu-plugin.','Link copied'=>'Ο σύνδεσμος αντιγράφηκε','link(s)'=>'σύνδεσμος(οι)','Links'=>'Σύνδεσμοι','Load available languages'=>'Φόρτωση διαθέσιμων γλωσσών','Load content'=>'Φόρτωση περιεχομένου','Loading…'=>'Φόρτωση…','Locale only'=>'Μόνο τοπική ρύθμιση','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Κλειδωμένο — ενεργό ένα συγκρουόμενο πρόσθετο SEO. Δείτε την ειδοποίηση παραπάνω.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Το Loco Translate αποθηκεύει τις προσαρμοσμένες μεταφράσεις του στον φάκελο wp-content/languages/loco/ — μια τοποθεσία που μπορεί να διαγραφεί σιωπηλά με ενημέρωση πυρήνα WP, επανεγκατάσταση πρόσθετου ή αν το Loco Translate αφαιρεθεί. Η αντιγραφή αρχείων εδώ τα μεταφέρει στον κατάλογο Lingua Forge i18n-overrides, ο οποίος διατηρείται μέσω όλων αυτών των γεγονότων και φορτώνεται αυτόματα σε κάθε αίτημα.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Αντιγραφή σε Ασφαλή Αποθήκευση','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Η χαμηλότερη δυνατότητα WordPress που επιτρέπεται να ενεργοποιήσει λειτουργίες AI. Η αυστηροποίηση αυτού σε ιστότοπους με πολλούς συγγραφείς αποτρέπει τους Συμβάλλοντες ή δοκιμαστικούς λογαριασμούς από την εκτέλεση πληρωμένων κλήσεων AI. Παρακάμπτεται ανά λειτουργία μέσω του φίλτρου linguaforge_required_capability.','Maintenance'=>'Συντήρηση','Maintenance Tab'=>'Καρτέλα Συντήρησης','Make casual'=>'Κάντε το ανεπίσημο','Make concise'=>'Κάντε το συνοπτικό','Make formal'=>'Κάντε το επίσημο','Mark citations needed'=>'Σημειώστε ότι χρειάζονται παραπομπές','Max context characters'=>'Μέγιστοι χαρακτήρες συμφραζομένων','Max hints characters'=>'Μέγιστοι χαρακτήρες υποδείξεων','Max input characters'=>'Μέγιστοι χαρακτήρες εισόδου','Max output tokens'=>'Μέγιστοι tokens εξόδου','Maximum characters accepted from the input field. Default: 8 000.'=>'Μέγιστοι χαρακτήρες που γίνονται αποδεκτοί από το πεδίο εισόδου. Προεπιλογή: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Μέγιστοι χαρακτήρες υπάρχοντος περιεχομένου ανάρτησης που περνιέται στην ΤΝ ως σπόρος συμφραζομένων όταν δεν παρέχονται Υποδείξεις. Προεπιλογή: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Μέγιστοι χαρακτήρες που διαβάζονται από το πεδίο Υποδείξεων. Προεπιλογή: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Μέγιστος αριθμός χαρακτήρων του περιεχομένου της ανάρτησης που προωθείται στην ΤΝ. 0 σημαίνει χωρίς όριο — το πλήρες περιεχόμενο αποστέλλεται πάντα (συνιστάται). Ορίστε μια μη μηδενική τιμή μόνο αν ο πάροχός σας έχει στενό πλαίσιο συμφραζομένων. Μια προειδοποίηση γράφεται στο αρχείο καταγραφής σφαλμάτων PHP κάθε φορά που το περιεχόμενο περικόπτεται.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Μέγιστος αριθμός tokens που μπορεί να παράγει η AI σε μια απάντηση μετάφρασης. Αν μια μετάφραση κόβεται σιωπηλά στο τέλος, αυξήστε αυτήν την τιμή. Προεπιλογή: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Μέγιστοι δείκτες που μπορεί να παράγει η ΤΝ ανά εκτέλεση δημιουργίας. Αυξήστε το αν τα πλήρη άρθρα κόβονται. Προεπιλογή: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Μέγιστοι δείκτες που μπορεί να παράγει η ΤΝ ανά γρήγορη μετάφραση. Προεπιλογή: 2.000.','Meta Description'=>'Μετα-περιγραφή','Meta description'=>'Μετα-περιγραφή','Meta Description, Excerpt Generator'=>'Μετα-περιγραφή, Δημιουργός περίληψης','Metric'=>'Μέτρο','Minimum role'=>'Ελάχιστος ρόλος','Missing pattern name or language.'=>'Λείπει όνομα μοτίβου ή γλώσσα.','Mode'=>'Λειτουργία','Model'=>'Μοντέλο','Model tier'=>'Επίπεδο μοντέλου','Models'=>'Μοντέλα','Models Tab (General)'=>'Γενική καρτέλα Μοντέλων','Modified'=>'Τροποποιήθηκε','Most recent cached block'=>'Πιο πρόσφατο αποθηκευμένο μπλοκ','Most recent cached response'=>'Πιο πρόσφατη αποθηκευμένη απάντηση','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Πολυγλωσσική δρομολόγηση, μετα-ετικέτες SEO και εργαλεία περιεχομένου AI για το WordPress. Συνδυάζει ανίχνευση γλώσσας, δρομολόγηση URL, hreflang, μετα-περιγραφές και λειτουργίες αποσπάσματος, μετα-ετικετών και μετάφρασης με τεχνητή νοημοσύνη.','Name displayed in this language. Leave empty to use the source name.'=>'Όνομα που εμφανίζεται σε αυτή τη γλώσσα. Αφήστε κενό για να χρησιμοποιήσετε το αρχικό όνομα.','Navigation'=>'Πλοήγηση','Navigation has no content to translate.'=>'Η πλοήγηση δεν έχει περιεχόμενο για μετάφραση.','Navigation not found.'=>'Δεν βρέθηκε πλοήγηση.','Navigation posts are translated via the Router tab, not this button.'=>'Οι δημοσιεύσεις πλοήγησης μεταφράζονται μέσω της καρτέλας Router, όχι με αυτό το κουμπί.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Η μετάφραση πλοήγησης απαιτεί ενεργό πάροχο AI. Διαμορφώστε ένα κλειδί API στην καρτέλα Κλειδιά API.','Navigations'=>'Πλοηγήσεις','Network error — could not reach the WordPress AJAX endpoint.'=>'Σφάλμα δικτύου — δεν ήταν δυνατή η πρόσβαση στο σημείο AJAX του WordPress.','No %s version found in this translation group.'=>'Δεν βρέθηκε έκδοση %s σε αυτήν την ομάδα μεταφράσεων.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Δεν απαιτείται ενέργεια. Η Google απενεργοποίησε το endpoint ping sitemap τον Ιανουάριο του 2024 και τώρα ανακαλύπτει τα sitemaps αποκλειστικά μέσω της οδηγίας Sitemap στο robots.txt — που έχει ήδη διαμορφώσει η LF. Η Google θα το εντοπίσει στην επόμενη ανίχνευσή της.','No AI provider configured.'=>'Δεν έχει διαμορφωθεί πάροχος AI.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Δεν έχει διαμορφωθεί πάροχος AI. Προσθέστε ένα κλειδί API στις Ρυθμίσεις → Κλειδιά API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Δεν έχει καταγραφεί χρήση AI στο επιλεγμένο παράθυρο (%s). Επιλέξτε ευρύτερο εύρος παραπάνω.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Δεν έχει καταγραφεί ακόμη χρήση AI. Μόλις ένας επεξεργαστής εκτελέσει μια μετάφραση, δημιουργήσει μια μετα-περιγραφή ή χρησιμοποιήσει οποιαδήποτε άλλη λειτουργία AI, τα σύνολα θα εμφανιστούν εδώ.','No API key configured for this provider.'=>'Δεν έχει διαμορφωθεί κλειδί API για αυτόν τον πάροχο.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Δεν υπάρχουν ενσωματωμένες οδηγίες — κάθε λειτουργία AI χρησιμοποιεί τις δικές της ρυθμίσεις. Συμπληρώστε το πεδίο Οδηγίες προσαρμοσμένου προτροπής παρακάτω για να προσθέσετε τους δικούς σας κανόνες σε όλο τον ιστότοπο.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Δεν ανιχνεύθηκαν συγκρουόμενα πρόσθετα SEO. Η Lingua Forge χειρίζεται αυτόνομα όλη την έξοδο SEO.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Δεν έχουν βρεθεί ακόμη προσαρμοσμένα αρχεία Loco Translate. Εμφανίζονται εδώ μόλις αποθηκεύσετε μια μετάφραση στο Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Δεν ανιχνεύθηκε εξωτερικό πρόσθετο OG. Η LF παράγει ολόκληρο το σετ OG + Twitter Card.','No file was selected.'=>'Δεν επιλέχθηκε αρχείο.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Δεν υπάρχουν καταχωρίσεις λεξικού που να ταιριάζουν με το τρέχον φίλτρο. Αφαιρέστε το φίλτρο για να δείτε όλες τις καταχωρίσεις ή προσθέστε μια νέα παρακάτω.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Δεν υπάρχουν ακόμα καταχωρίσεις λεξικού. Προσθέστε μία παρακάτω για να αρχίσετε να επιβάλλετε ορολογία στις μεταφράσεις.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Δεν βρέθηκε H1. Συνήθως ο τίτλος της ανάρτησης είναι το H1 — επαληθεύστε ότι το θέμα σας το παράγει.','No images found in content.'=>'Δεν βρέθηκαν εικόνες στο περιεχόμενο.','No internal links found to update.'=>'Δεν βρέθηκαν εσωτερικοί σύνδεσμοι για ενημέρωση.','No language-specific template parts found to map.'=>'Δεν βρέθηκαν τμήματα προτύπου που να χρειάζονται χαρτογράφηση.','No LF meta description set — using excerpt/content.'=>'Δεν έχει οριστεί μετα-περιγραφή LF — χρησιμοποιώντας απόσπασμα/περιεχόμενο.','No links found. Internal links improve crawlability and user navigation.'=>'Δεν βρέθηκαν σύνδεσμοι. Οι εσωτερικοί σύνδεσμοι βελτιώνουν την ανίχνευση και την πλοήγηση των χρηστών.','No meta description found. Generate one via the AI meta description feature.'=>'Δεν βρέθηκε μετα-περιγραφή. Δημιουργήστε μία μέσω της λειτουργίας μετα-περιγραφής AI.','No navigation references needed updating.'=>'Δεν χρειάζεται ενημέρωση αναφορών πλοήγησης.','No override files uploaded yet.'=>'Δεν έχουν ανέβει ακόμη αρχεία παρακάμψεων.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Δεν βρέθηκε φυσικό αρχείο robots.txt. Το WordPress το δημιουργεί εικονικά και η οδηγία Sitemap της LF περιλαμβάνεται αυτόματα.','No published posts found for the selected filters.'=>'Δεν βρέθηκαν δημοσιευμένες αναρτήσεις για τα επιλεγμένα φίλτρα.','No response from AI provider. Check your API key and try again.'=>'Δεν λαμβάνεται απάντηση από τον πάροχο AI. Ελέγξτε το κλειδί API και δοκιμάστε ξανά.','No response from provider — check the error log for details.'=>'Δεν υπάρχει απάντηση από τον πάροχο — ελέγξτε το αρχείο σφαλμάτων για λεπτομέρειες.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Δεν έχουν διαμορφωθεί δευτερεύουσες γλώσσες. Εγκαταστήστε ένα πακέτο γλώσσας παραπάνω για να ενεργοποιήσετε το πλαίσιο προτύπων.','No source content found to translate.'=>'Δεν βρέθηκε περιεχόμενο πηγής για μετάφραση.','No source page linked yet.'=>'Δεν έχει ακόμη συσχετιστεί σελίδα πηγής.','No template part references needed updating.'=>'Δεν χρειάζεται ενημέρωση αναφορών τμήματος προτύπου.','No title set.'=>'Δεν έχει οριστεί τίτλος.','No translated content found. The sitemap will populate once posts have been translated.'=>'Δεν βρέθηκε μεταφρασμένο περιεχόμενο. Το sitemap θα γεμίσει μόλις μεταφραστούν οι αναρτήσεις.','No translation found — analyzed the source language version.'=>'Δεν βρέθηκε μετάφραση — αναλύθηκε η έκδοση της πηγής γλώσσας.','No {lang} translation registered (TRID missing)'=>'Δεν έχει καταχωρηθεί μετάφραση {lang} (TRID λείπει)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Δεν έχει ακόμη δημιουργηθεί. Το sitemap δημιουργείται κατά την πρώτη επίσκεψη στη διεύθυνση sitemap και αποθηκεύεται στην cache για 24 ώρες.','Notes'=>'Σημειώσεις','Nothing — all types disabled'=>'Τίποτα — όλοι οι τύποι απενεργοποιημένοι','Notice message'=>'Μήνυμα ειδοποίησης','Notice settings'=>'Ρυθμίσεις ειδοποίησης','Notify search engines'=>'Ειδοποίηση μηχανών αναζήτησης','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Ετικέτες OG/Twitter Card: διαχειρίζεται από το module Open Graph της LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Παλαιότερο αποθηκευμένο μπλοκ','Oldest cached response'=>'Παλαιότερη αποθηκευμένη απάντηση','Only .mo files are accepted.'=>'Επιτρέπονται μόνο αρχεία .mo.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Open Graph output'=>'Έξοδος Open Graph','Open Graph settings saved.'=>'Οι ρυθμίσεις Open Graph αποθηκεύτηκαν.','Open Search Console →'=>'Άνοιγμα Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Ανοίξτε το εγγενές φύλλο κοινής χρήσης ιστού του περιηγητή (iOS, Android, μερικοί επιτραπέζιοι υπολογιστές). Επιστρέφει στην αντιγραφή στο clipboard αν δεν υποστηρίζεται.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Προαιρετικό πλαίσιο για τους επεξεργαστές (π.χ. "ASIC = Εξειδικευμένο ολοκληρωμένο κύκλωμα εφαρμογής; διατηρείται στα Αγγλικά σε τεχνικά πλαίσια").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Προαιρετικό. Το Bing διαβάζει ήδη τη οδηγία Sitemap: από το robots.txt — αυτό ενεργοποιεί άμεση επανεξέταση αντί να περιμένει την επόμενη προγραμματισμένη.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Προαιρετικό. Το Yandex διαβάζει ήδη τη οδηγία Sitemap: από το robots.txt — αυτό ενεργοποιεί άμεση επανεξέταση αντί να περιμένει την επόμενη προγραμματισμένη.','Output'=>'Αποτέλεσμα','Output Article or WebPage schema on singular posts and pages'=>'Εξαγωγή σχήματος Article ή WebPage σε μεμονωμένες αναρτήσεις και σελίδες','Output hreflang tags in wp_head'=>'Εξαγωγή ετικετών hreflang στο wp_head','Output mode'=>'Λειτουργία εξαγωγής','Output Open Graph tags in wp_head'=>'Εξαγωγή ετικετών Open Graph στο wp_head','Output Product schema on WooCommerce product pages'=>'Εξαγωγή σχήματος Προϊόντος σε σελίδες προϊόντων WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Έξοδος Schema.org JSON-LD στο wp_head','Output tokens'=>'Εξαγωγικά tokens','Output WebSite schema on the front page and blog index'=>'Έξοδος schema Ιστότοπου στη αρχική σελίδα και στον κατάλογο ιστολογίου','Overall SEO score'=>'Συνολική βαθμολογία SEO','overridden'=>'υπερβαλλόμενο','Override file deleted.'=>'Το αρχείο παρακάμψεων διαγράφηκε.','Override file uploaded successfully.'=>'Το αρχείο παρακάμψεων ανέβηκε με επιτυχία.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Παρακάμπτει την προεπιλογή AI για Μετάφραση και Δημιουργία Περιεχομένου σε αυτήν τη σελίδα. Όλες οι άλλες λειτουργίες πάντα χρησιμοποιούν την παγκόσμια προεπιλογή.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Παρακάμπτει την προεπιλογή AI για Μετάφραση και Δημιουργία Περιεχομένου σε αυτήν τη σελίδα. Οι προσαρμοσμένες οδηγίες προτροπής σε όλο τον ιστότοπο (Ρυθμίσεις → Συμπεριφορά) προστίθενται πάντα σε κάθε αίτημα, ανεξάρτητα από αυτήν την επιλογή.','Overview'=>'Επισκόπηση','Page'=>'Σελίδα','Part'=>'Μέρος','Paste a footnote, sentence, or any snippet here…'=>'Επικολλήστε μια υποσημείωση, πρόταση ή οποιοδήποτε απόσπασμα εδώ…','Paste text, or select text in the editor first…'=>'Επικολλήστε κείμενο, ή επιλέξτε κείμενο στον επεξεργαστή πρώτα…','Paste text, or select text on the page first…'=>'Επικολλήστε κείμενο, ή επιλέξτε κείμενο στη σελίδα πρώτα…','Paste your API key…'=>'Επικολλήστε το κλειδί API σας…','Path prefix — example.com/de/'=>'Πρόθεμα διαδρομής — example.com/de/','Pattern'=>'Μοτίβο','Pattern has no content to translate.'=>'Το μοτίβο δεν έχει περιεχόμενο για μετάφραση.','Pattern not found.'=>'Το μοτίβο δεν βρέθηκε.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Το μοτίβο μεταφράστηκε και αποθηκεύτηκε. Αντιγράψτε το περιεχόμενο στη δημοσίευση CPT μέσω του επεξεργαστή μπλοκ ή χρησιμοποιήστε το ως σημείο εκκίνησης για ένα Επαναχρησιμοποιήσιμο Μπλοκ.','Pattern translation failed.'=>'Αποτυχία μετάφρασης μοτίβου.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Προσωρινή μνήμη ανά ανάρτηση για μεταφράσεις που παράγονται από AI, μετα-περιγραφές, αποσπάσματα και περιεχόμενο. Πάντα ενεργό — δεν απαιτεί ξεχωριστή εναλλαγή. Οι καταχωρίσεις ακυρώνονται αυτόματα όταν αλλάζει το περιεχόμενο ή ο πάροχος/μοντέλο AI.','Permalink rules flushed successfully.'=>'Οι κανόνες permalink εκκαθαρίστηκαν με επιτυχία.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Οριστικά διαγράφει όλα τα πρότυπα, μέρη προτύπων, μοτίβα, μενού πλοήγησης, αναρτήσεις, σελίδες, προσαρμοσμένους τύπους αναρτήσεων, προϊόντα και παραλλαγές προϊόντων που σχετίζονται με αυτή τη γλώσσα. Ακόμα και διαγράφει τα αρχεία πακέτου locale του WordPress ώστε αυτή η γλώσσα να μην εμφανίζεται πλέον στον δρομολογητή. Αυτή η ενέργεια δεν μπορεί να αναιρεθεί.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Οριστικά απεγκαθιστάτε το %s; Αυτό θα διαγράψει όλο το μεταφρασμένο περιεχόμενο για αυτή τη γλώσσα και δεν μπορεί να αναιρεθεί.','Permission denied.'=>'Άρνηση άδειας πρόσβασης.','Persuasive'=>'Πειστικό','PHP constant'=>'σταθερά PHP','Pin on Pinterest'=>'Καρφιτσώστε στο Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Καρφιτσώστε όρους που δεν πρέπει να μεταφραστούν ή πρέπει πάντα να αποδίδονται με συγκεκριμένο τρόπο (π.χ. ονόματα εμπορικών σημάτων, ονόματα προϊόντων, ακρωνύμια). Οι περιορισμοί γλωσσάρι εισάγονται σε κάθε αίτημα μετάφρασης AI για όλες τις λειτουργίες: μετάφραση ανάρτησης, μετα-περιγραφή, απόσπασμα και μετάφραση προτύπου FSE.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Απλή γλώσσα','Please enter some instructions first…'=>'Παρακαλώ εισάγετε πρώτα κάποιες οδηγίες…','Please enter some text first…'=>'Παρακαλώ εισάγετε κάποιο κείμενο πρώτα…','Plugin'=>'Πρόσθετο','Post'=>'Ανάρτηση','Post not found or not published.'=>'Δεν βρέθηκε ή δεν δημοσιεύτηκε η ανάρτηση.','Post not found.'=>'Η ανάρτηση δεν βρέθηκε.','Post on X / Twitter'=>'Ανάρτηση στο X / Twitter','Post Types'=>'Τύποι Ανάρτησης','Prefilled from excerpt. Edit to override.'=>'Προεπιλεγμένο από απόσπασμα. Επεξεργαστείτε για να το αντικαταστήσετε.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Η τιμή και η διαθεσιμότητα αντανακλούν πάντα το προϊόν της πηγής (μοναδικό μοντέλο αποθέματος). Οι ετικέτες εμφανίζονται μόνο όταν το module Open Graph του LF είναι ρυθμισμένο σε "Πλήρες" ή "Αυτόματο" χωρίς ανιχνευμένο συγκρουόμενο plugin SEO.','Primary Language'=>'Κύρια γλώσσα','Primary language'=>'Κύρια γλώσσα','Primary language saved.'=>'Αποθηκεύτηκε η κύρια γλώσσα.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Βασική γλώσσα: η γλώσσα στην οποία είναι γραμμένο το υπάρχον περιεχόμενό σας. Όλες οι μεταφράσεις παράγονται από αυτήν τη γλώσσα. Η αλλαγή της δεν μετακινεί ή διαγράφει αναρτήσεις.','Processing…'=>'Επεξεργασία…','Product'=>'Προϊόν','Product Open Graph'=>'Open Graph Προϊόν','Product — WooCommerce product pages'=>'Προϊόν — σελίδες προϊόντων WooCommerce','Provider'=>'Πάροχος','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Ο πάροχος δεν επέστρεψε κείμενο. Ελέγξτε το αρχείο καταγραφής σφαλμάτων του WordPress για τον λεπτομερή λόγο αποτυχίας.','Quality'=>'Ποιότητα','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Ποιότητα (προεπιλογή — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Ποιότητα (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Ποιότητα: χρησιμοποιείται για μετάφραση ανάρτησης και δημιουργία περιεχομένου — υψηλότερη ποιότητα, υψηλότερο κόστος.','Quick Translate'=>'Γρήγορη μετάφραση','Quick Translation'=>'Γρήγορη Μετάφραση','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Η Γρήγορη Μετάφραση χρησιμοποιείται για λειτουργία αποσπάσματος/κομματιού — σύντομες περικοπές μεταφράζονται κατ\' απαίτηση από τη γραμμή εργαλείων, τον επεξεργαστή ή τα αναδυόμενα παράθυρα μπλοκ. Χρησιμοποιεί μια ξεχωριστή, ελαφρύτερη διαμόρφωση από τη μετάφραση σε πλήρη σελίδα για να διατηρεί τις απαντήσεις γρήγορες και οικονομικές.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Ενεργοποιεί ξανά το canLockBlocks του Gutenberg. Χρησιμότητα για πρότυπα επιμέλειας που πρέπει να αποτρέπουν τους συνεισφέροντες από τη μετακίνηση ή διαγραφή συγκεκριμένων μπλοκ.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Ενεργοποιεί ξανά το supportsTemplateMode. Βασικό για τις ροές εργασίας Full-Site-Editing όπου οι υπεροχές προτύπων σε επίπεδο δημοσίευσης είναι σκόπιμες.','Re-generates and updates the cached result.'=>'Αναδημιουργεί και ενημερώνει το αποθηκευμένο αποτέλεσμα.','Re-scan'=>'Επανασάρωση','Re-scanning…'=>'Επανεξέταση…','Re-translate'=>'Επαναμετάφραση','Reading time'=>'Χρόνος ανάγνωσης','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Ανακατεύθυνση επισκεπτών στη προτιμώμενη γλώσσα τους βάσει της κεφαλίδας Accept-Language του περιηγητή','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Βελτίωση περαιτέρω — π.χ. "κάντε το πιο σύντομο" ή "χρησιμοποιήστε επίσημο τόνο"…','Refine further:'=>'Βελτιώστε περαιτέρω:','Refinement'=>'Βελτίωση','Refinement failed — please try again.'=>'Η βελτίωση απέτυχε — παρακαλώ δοκιμάστε ξανά.','Refining…'=>'Βελτιώνεται…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Αναγεννά τους κανόνες επαναγραφής του WordPress ώστε τα προθέματα URL, τα συγκεκριμένα για τη γλώσσα slug και οι ανακατατάξεις αρχείων να είναι συγχρονισμένα. Απαραίτητο μετά την αλλαγή της κύριας γλώσσας ή την προσθήκη νέας υποστήριξης γλώσσας.','Remove stored key'=>'Αφαίρεση αποθηκευμένου κλειδιού','Report an issue on GitHub'=>'Αναφορά προβλήματος στο GitHub','Request failed — please try again.'=>'Το αίτημα απέτυχε — παρακαλώ δοκιμάστε ξανά.','Request failed.'=>'Το αίτημα απέτυχε.','Request failed. Check your connection.'=>'Το αίτημα απέτυχε. Ελέγξτε τη σύνδεσή σας.','Request failed. Please try again.'=>'Το αίτημα απέτυχε. Παρακαλώ δοκιμάστε ξανά.','Requests'=>'Αιτήματα','Reset'=>'Επαναφορά','Result will appear here…'=>'Το αποτέλεσμα θα εμφανιστεί εδώ…','Retranslate'=>'Επαναμετάφραση','Retranslating…'=>'Επαναμεταφράζοντας…','Review carefully — links and slugs not updated.'=>'Ελέγξτε προσεκτικά — οι σύνδεσμοι και τα slugs δεν ενημερώθηκαν.','Review translation before applying'=>'Ελέγξτε τη μετάφραση πριν την εφαρμόσετε','Revise'=>'Επανεξέταση','Revision'=>'Αναθεώρηση','Revision Type'=>'Τύπος αναθεώρησης','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'Το robots.txt ενημερώθηκε με οδηγία Sitemap.','Router'=>'Δρομολογητής','Router Tab'=>'Καρτέλα δρομολογητή','Run AI Analysis'=>'Εκτέλεση ανάλυσης AI','Save Debug Setting'=>'Αποθήκευση ρύθμισης αποσφαλμάτωσης','Save Hreflang Settings'=>'Αποθήκευση ρυθμίσεων Hreflang','Save Open Graph Settings'=>'Αποθήκευση ρυθμίσεων Open Graph','Save Router Settings'=>'Αποθήκευση Ρυθμίσεων Δρομολογητή','Save Schema.org Settings'=>'Αποθήκευση ρυθμίσεων Schema.org','Save Settings'=>'Αποθήκευση ρυθμίσεων','Save Sitemap Settings'=>'Αποθήκευση ρυθμίσεων Sitemap','Save Social Share Settings'=>'Αποθήκευση ρυθμίσεων Κοινωνικής Μοιρασιάς','Save the post to persist changes.'=>'Αποθηκεύστε τη δημοσίευση για να διατηρήσετε τις αλλαγές.','Save Uninstall Setting'=>'Αποθήκευση ρύθμισης απεγκατάστασης','Save WooCommerce SEO Settings'=>'Αποθήκευση ρυθμίσεων SEO WooCommerce','Saved to the meta description field when you apply.'=>'Αποθηκεύτηκε στο πεδίο μετα-περιγραφής κατά την εφαρμογή.','Scan failed: '=>'Η σάρωση απέτυχε: ','Scan request failed. Please try again.'=>'Απέτυχε το αίτημα σάρωσης. Παρακαλώ δοκιμάστε ξανά.','Scanning posts for broken language links…'=>'Ανίχνευση αναρτήσεων για σπασμένους συνδέσμους γλώσσας…','Schema output deferred.'=>'Η έξοδος Schema αναβλήθηκε.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Έξοδος Schema.org','Schema.org settings saved.'=>'Οι ρυθμίσεις Schema.org αποθηκεύτηκαν.','Search'=>'Αναζήτηση','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Το Search Console είναι χρήσιμο για την παρακολούθηση σφαλμάτων ευρετηρίασης και κάλυψης, αλλά δεν είναι απαραίτητο για την ανίχνευση.','Search Results'=>'Αποτελέσματα Αναζήτησης','Security check failed — file path is not permitted.'=>'Απέτυχε ο έλεγχος ασφαλείας — η διαδρομή αρχείου δεν επιτρέπεται.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Επιλέξτε μια γλώσσα για να διαχειριστείτε τα πρότυπα FSE, τα μέρη προτύπων και τα μενού πλοήγησης.','Select language'=>'Επιλογή γλώσσας','Send via Telegram'=>'Αποστολή μέσω Telegram','Send via WhatsApp'=>'Αποστολή μέσω WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Ανάλυση SEO','SEO character-count info'=>'Πληροφορίες χαρακτήρων SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Εντοπίστηκαν plugin(τα) SEO: %s. Το LF εμφανίζει μόνο og:locale και og:locale:alternate; το ανιχνευμένο plugin χειρίζεται ολόκληρο το σετ OG.','SEO plugins and conflict avoidance:'=>'Plugins SEO και αποφυγή συγκρούσεων:','SEO Tab'=>'Καρτέλα SEO','Server setup (subdomain)'=>'Ρύθμιση διακομιστή (υποτομέας)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Ορίζει τη προεπιλεγμένη συμπεριφορά AI για όλες τις λειτουργίες σε ολόκληρο τον ιστότοπο. Τα μεμονωμένα δημοσιεύματα μπορούν να το παρακάμψουν για Μετάφραση και Δημιουργία Περιεχομένου μέσω του μετα-κουτιού Lingua Forge.','Settings'=>'Ρυθμίσεις','Settings saved.'=>'Οι ρυθμίσεις αποθηκεύτηκαν.','Share on Facebook'=>'Μοιραστείτε στο Facebook','Share on LinkedIn'=>'Μοιραστείτε στο LinkedIn','Share on Mastodon'=>'Μοιραστείτε στο Mastodon','Share via email (mailto:)'=>'Μοιραστείτε μέσω email (mailto:)','Show home link'=>'Εμφάνιση συνδέσμου αρχικής','Shown when no translation exists for the visitor\'s language.'=>'Εμφανίζεται όταν δεν υπάρχει μετάφραση για τη γλώσσα του επισκέπτη.','Single'=>'Μοναδικό','Single %s'=>'Μονό %s','Single: %s'=>'Μονό: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Επίπεδο ορίου AI σε όλο τον ιστότοπο ανά UTC ημέρα (μετρά τόσο τις μεταφράσεις Toolbar όσο και τις αναθεωρήσεις μπλοκ). Η καταμέτρηση επαναφέρεται τα μεσάνυχτα UTC. Ορίστε το σε 0 για απενεργοποίηση του ορίου.','Sitemap'=>'Χάρτης ιστότοπου','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Ο προσωρινός αποθηκευτικός χώρος του Sitemap καθαρίστηκε. Θα αναδημιουργηθεί στην επόμενη επίσκεψη στη διεύθυνση URL του sitemap.','Sitemap output'=>'Έξοδος Sitemap','Sitemap settings saved.'=>'Οι ρυθμίσεις Sitemap αποθηκεύτηκαν.','Sitemap URL'=>'Διεύθυνση URL Sitemap','Size'=>'Μέγεθος','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Κοινή χρήση μπλοκ κοινωνικών εικονιδίων: URLs: διαχειρίζεται από το ενσωματωμένο Κοινωνικό Μοιρασιά LF (SEO → Κοινωνική Μοιρασιά)','Social Share'=>'Κοινωνική Μοιρασιά','Social Share settings saved.'=>'Οι ρυθμίσεις Κοινωνικής Κοινοποίησης αποθηκεύτηκαν.','Some link fixes failed.'=>'Ορισμένες διορθώσεις συνδέσμων απέτυχαν.','Some nav ref fixes failed.'=>'Ορισμένες διορθώσεις αναφορών πλοήγησης απέτυχαν.','Some part fixes failed.'=>'Ορισμένες διορθώσεις μερών απέτυχαν.','Some parts could not be created.'=>'Ορισμένα μέρη δεν μπόρεσαν να δημιουργηθούν.','Some templates could not be created.'=>'Ορισμένα πρότυπα δεν μπόρεσαν να δημιουργηθούν.','Some translations failed.'=>'Ορισμένες μεταφράσεις απέτυχαν.','source'=>'πηγή','Source file not found.'=>'Το αρχείο πηγής δεν βρέθηκε.','Source lang'=>'Γλώσσα πηγής','Source language'=>'Γλώσσα πηγής','Source term'=>'Όρος πηγής','Standard'=>'Τυπικό','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Η Standard χρησιμοποιεί τη δική της ρυθμισμένη θερμοκρασία κάθε λειτουργίας: Μετάφραση T=0.2 (ακριβής), Γρήγορη Μετάφραση T=0.4, Δημιουργία Περιεχομένου T=0.6 (δημιουργική). Οι άλλες προεπιλογές εφαρμόζουν μια σταθερή θερμοκρασία σε όλες τις λειτουργίες.','Status'=>'Κατάσταση','Status / Actions'=>'Κατάσταση / Ενέργειες','Storytelling'=>'Αφήγηση','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Λειτουργία αυστηρής διατήρησης για νομικό, κανονιστικό, ιατρικό ή τεχνικό περιεχόμενο. Όταν είναι ενεργό, κάθε λειτουργία AI χρησιμοποιεί χαμηλή θερμοκρασία δειγματοληψίας και προσθέτει το προσάρτημα παρακάτω στην προτροπή του συστήματος — η ορολογία, οι αριθμοί άρθρων, οι μονάδες, τα ονόματα εμπορικών σημάτων και η κανονιστική γλώσσα διατηρούνται αυτούσια και όχι παραφρασμένα.','Structured Outline'=>'Δομημένη περίληψη','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Ο τρόπος υποτομέα απαιτεί από τον διακομιστή σας να δείχνει όλους τους υποτομείς γλώσσας (π.χ. de.example.com) σε αυτήν την εγκατάσταση WordPress. Μετά την αλλαγή τρόπου, καθαρίστε τους κανόνες permalink και διαγράψτε τυχόν cache. Αν η αρχική URL περιλαμβάνει www (π.χ. www.example.com), χρησιμοποιήστε το φίλτρο lf_base_domain για να ορίσετε το απλό ανώτατο domain ώστε οι υποτομείς να κατασκευάζονται σωστά.','Subdomain — de.example.com/'=>'Υποτομέας — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Υποβάλετε αυτό το URL στη Google Search Console μαζί με το κύριο sitemap σας.','Submit to Reddit'=>'Υποβολή στο Reddit','Suggested meta description'=>'Προτεινόμενη μετα-περιγραφή','Suggested title'=>'Προτεινόμενος τίτλος','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Υποστηριζόμενοι πάροχοι: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Μόνο ένας πάροχος είναι ενεργός κάθε φορά. Επιλέξτε τον ενεργό πάροχο στην καρτέλα Γενικά.','Suppressed: %s.'=>'Κατασταλμένο: %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ανά λειτουργία','Tag'=>'Ετικέτα','Tags emitted'=>'Ετικέτες που εκπέμπονται','Target lang'=>'Γλώσσα στόχου','Target Language'=>'Γλώσσα προορισμού','Target language'=>'Γλώσσα στόχου','Target term'=>'Όρος στόχου','Target: 140–160 chars for optimal SERP display'=>'Στόχος: 140–160 χαρακτήρες για βέλτιστη εμφάνιση στη SERP','Technical'=>'Τεχνικό','Technical / Scientific'=>'Τεχνικό / Επιστημονικό','Technical / Scientific instructions'=>'Τεχνικές / Επιστημονικές οδηγίες','Template "%s" already exists.'=>'Το πρότυπο "%s" υπάρχει ήδη.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Το πρότυπο "{expected}" δεν υπάρχει — δημιουργήστε το πρώτα στον Επεξεργαστή Ιστοσελίδων.','Template has no content.'=>'Το πρότυπο δεν έχει περιεχόμενο.','Template mode'=>'Λειτουργία προτύπου','Template not found or not stored in the database.'=>'Το πρότυπο δεν βρέθηκε ή δεν αποθηκεύτηκε στη βάση δεδομένων.','Template part "%s" already exists.'=>'Το τμήμα προτύπου "%s" υπάρχει ήδη.','Template part has no content.'=>'Το τμήμα προτύπου δεν έχει περιεχόμενο.','Template part not found or not stored in the database.'=>'Το τμήμα προτύπου δεν βρέθηκε ή δεν αποθηκεύτηκε στη βάση δεδομένων.','Template Parts'=>'Μέρη προτύπων','Templates'=>'Πρότυπα','Test connection'=>'Δοκιμή σύνδεσης','Testing…'=>'Δοκιμή…','Text domain / locale'=>'Τομέας / τοπική ρύθμιση','Text to translate'=>'Κείμενο προς μετάφραση','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Η Cache Απαντήσεων API αποθηκεύει το ακατέργαστο αποτέλεσμα κάθε αίτησης AI — μετάφραση, μετα-περιγραφή, απόσπασμα και δημιουργία περιεχομένου — με κλειδί έναν κατακερματισμό των εισόδων (περιεχόμενο, ζεύγος γλωσσών, πάροχος, μοντέλο). Οι επόμενες αιτήσεις με τα ίδια δεδομένα εξυπηρετούνται από την cache χωρίς κλήση API. Η cache διαφέρει από τη Μνήμη Μετάφρασης: η Μνήμη Μετάφρασης λειτουργεί σε επίπεδο μπλοκ και μοιράζεται μεταξύ αναρτήσεων. Η Cache Απαντήσεων API λειτουργεί σε επίπεδο λειτουργίας και είναι κλειδωμένη ανά ανάρτηση.','The editor did not accept the content — please try again.'=>'Ο επεξεργαστής δεν αποδέχτηκε το περιεχόμενο — παρακαλώ δοκιμάστε ξανά.','The following directive is active in your virtual robots.txt:'=>'Η ακόλουθη οδηγία είναι ενεργή στο εικονικό αρχείο robots.txt σας:','The lf-social-share mu-plugin is active.'=>'Το πρόσθετο lf-social-share είναι ενεργό.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Το ενσωματωμένο Κοινωνικό Μοιρασιά της Lingua Forge είναι ανενεργό — το πρόσθετο διαχειρίζεται την ανακατεύθυνση URL κοινής χρήσης και τις ενέργειες JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Το επίπεδο Light χρησιμοποιεί το γρήγορο μοντέλο που διαμορφώνεται στον πίνακα Μοντέλων παραπάνω (προεπιλογή: Haiku / Flash). Μεταβείτε στην Ποιότητα αν χρειάζεστε την ίδια ακρίβεια μετάφρασης με τη λειτουργία πλήρους σελίδας για αποσπάσματα.','The phrase as it appears in the source text.'=>'Η φράση όπως εμφανίζεται στο πρωτότυπο κείμενο.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Η κύρια γλώσσα σερβίρεται πάντα στην ρίζα του ιστότοπού σας — χωρίς πρόθεμα URL στη διαδρομή σε λειτουργία μονοπατιού, χωρίς υποτομέα γλώσσας σε λειτουργία υποτομέα. Όλες οι άλλες γλώσσες χρησιμοποιούν είτε πρόθεμα διαδρομής /lang/ (π.χ. example.com/de/) είτε υποτομέα γλώσσας (π.χ. de.example.com), ανάλογα με τη ρύθμιση δομής URL παρακάτω.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Η καρτέλα SEO → Συμβατότητα δείχνει την κατάσταση ανίχνευσης σε πραγματικό χρόνο και εξηγεί ακριβώς τι κάνει το LF για κάθε περιοχή λειτουργίας.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'Το URL κοινής χρήσης πάντα αντικατοπτρίζει την τρέχουσα σελίδα — δεν χρειάζεται χειροκίνητη εισαγωγή URL. Το φίλτρο linguaforge_social_share_url σας επιτρέπει να παρακάμψετε το επιλυμένο URL για οποιαδήποτε υπηρεσία.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Το sitemap ανακοινώνεται αυτόματα στο robots.txt. Όλοι οι μεγάλοι μηχανές αναζήτησης — Google, Bing, Yandex — το ανακαλύπτουν από το robots.txt. Δεν απαιτείται χειροκίνητη υποβολή.','The source page has no footnotes.'=>'Η σελίδα πηγής δεν έχει υποσημειώσεις.','The upload failed — please try again.'=>'Η μεταφόρτωση απέτυχε — παρακαλώ δοκιμάστε ξανά.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Το sitemap του WordPress περιλαμβάνει όλους τους URL περιεχομένου σας. Το sitemap LF δείχνει στις μηχανές αναζήτησης πώς οι εκδόσεις γλώσσας σχετίζονται μεταξύ τους μέσω εναλλακτικών xhtml:link hreflang. Υποβάλετε και τα δύο στο Google Search Console για πλήρη κάλυψη.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Αυτές οι υποσημειώσεις προέρχονται από τη σελίδα πηγής και εμφανίζονται εδώ μόνο για αναφορά. Προσθέστε τες σε αυτή τη σελίδα χρησιμοποιώντας τον επεξεργαστή μπλοκ.','This is the source page. Footnotes are edited directly in the block editor.'=>'Αυτή είναι η αρχική σελίδα. Οι υποσημειώσεις επεξεργάζονται απευθείας στον επεξεργαστή μπλοκ.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Αυτό το κλειδί παρέχεται αυτήν τη στιγμή από έναν διακομιστή %s και δεν μπορεί να αφαιρεθεί εδώ. Εισάγετε ένα νέο κλειδί παραπάνω για να το αντικαταστήσετε με μια τιμή βάσης δεδομένων.','This language is protected and cannot be uninstalled.'=>'Αυτή η γλώσσα προστατεύεται και δεν μπορεί να απεγκατασταθεί.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Αυτή η γλώσσα ταιριάζει με την τοπική ρύθμιση του WordPress και δεν μπορεί να απεγκατασταθεί.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Συμβουλή: για να επαναφέρετε ένα μοντέλο στην ενσωματωμένη προεπιλογή, διαγράψτε το πεδίο και αποθηκεύστε.','Title'=>'Τίτλος','Title is %d chars — aim for 50–60.'=>'Ο τίτλος έχει %d χαρακτήρες — στόχος 50–60.','Title is %d chars — may be truncated in SERPs (aim for 50–60).'=>'Ο τίτλος έχει %d χαρακτήρες — ενδέχεται να περικοπεί στα SERPs (στόχος 50–60).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Για να χρησιμοποιήσετε ένα προσαρμοσμένο μυστικό κρυπτογράφησης (αντί της προεπιλεγμένης τιμής wp_salt), προσθέστε το αυτό στο wp-config.php:','Today'=>'Σήμερα','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Η κατανάλωση tokens καταγράφεται ανά λειτουργία, πάροχο και μοντέλο. Καταγράφεται σε κάθε επιτυχημένη κλήση AI; οι δοκιμές σύνδεσης εξαιρούνται ώστε να μην επηρεάζουν τα συνολικά.','Tone'=>'Τόνος','tone'=>'τόνος','Tone:'=>'Τόνος:','Too many AI requests. Please retry in %d seconds.'=>'Πάρα πολλά αιτήματα AI. Παρακαλώ δοκιμάστε ξανά σε %d δευτερόλεπτα.','Total'=>'Σύνολο','Total tokens'=>'Σύνολο tokens','Translate'=>'Μετάφραση','Translate / Revise'=>'Μετάφραση / Αναθεώρηση','Translate / Revise block'=>'Μεταφραστικό / Αναθεωρητικό μπλοκ','Translate all'=>'Μετάφραση όλων','Translate chunk'=>'Μεταφράστε το τμήμα','Translate Content'=>'Μετάφραση περιεχομένου','Translate missing'=>'Αποτυχία μετάφρασης','Translate page…'=>'Μετάφραση σελίδας…','Translated content'=>'Μεταφρασμένο περιεχόμενο','Translated Names'=>'Μεταφρασμένα ονόματα','Translated title'=>'Μεταφρασμένος τίτλος','Translated to:'=>'Μεταφράστηκε σε:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Μεταφράστηκε. Ανασκόπηση στον Επεξεργαστή Ιστότοπου — οι εσωτερικοί σύνδεσμοι, οι διευθύνσεις URL πλοήγησης και τα ονόματα προτύπων δεν ενημερώνονται αυτόματα.','Translating…'=>'Μεταφράζοντας…','Translation'=>'Μετάφραση','Translation Caching'=>'Αποθήκευση cache μεταφράσεων','Translation found but permalink could not be generated'=>'Βρέθηκε μετάφραση, αλλά ο σύνδεσμος μόνιμης αναφοράς δεν μπόρεσε να δημιουργηθεί','Translation Limits'=>'Όρια Μετάφρασης','Translation Limits & Behavior'=>'Όρια και συμπεριφορά μετάφρασης','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Όρια μετάφρασης: ελέγξτε ποιοι ρόλοι χρηστών μπορούν να ενεργοποιήσουν τη μετάφραση AI και ορίστε έναν μηνιαίο προϋπολογισμό tokens. Η υπέρβαση του προϋπολογισμού διακόπτει τις κλήσεις AI μέχρι την επαναφορά του μήνα.','Translation Memory'=>'Μνήμη Μετάφρασης','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Η μνήμη μεταφράσεων αποθηκεύει τα αποτελέσματα AI με βάση το περιεχόμενο, το ζεύγος γλωσσών, τον πάροχο και το μοντέλο. Η επεξεργασία μιας ανάρτησης ακυρώνει την καταχώριση cache, ώστε η επόμενη κλήση μετάφρασης να λαμβάνει φρέσκο αποτέλεσμα.','Translation Memory cleared. %d cached block was removed.'=>'Η μνήμη μετάφρασης διαγράφηκε. %d αποθηκευμένα μπλοκ αφαιρέθηκαν.' . "\0" . 'Η μνήμη μετάφρασης διαγράφηκε. %d αποθηκευμένα μπλοκ αφαιρέθηκαν.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Μνήμη Μετάφρασης: αποθηκεύει ολόκληρη την μεταφρασμένη ανάρτηση ανά περιεχόμενο. Διαγράψτε την όταν θέλετε να αναγκάσετε μια επανεπεξεργασία όλων των αναρτήσεων, ανεξάρτητα αν το περιεχόμενό τους άλλαξε.','Translation workflow'=>'Ροή εργασίας μετάφρασης','Translation, Content Generator'=>'Μετάφραση, Δημιουργός Περιεχομένου','Type'=>'Τύπος','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Απεγκατάσταση %s','Uninstall Behaviour'=>'Απεγκατάσταση Συμπεριφοράς','Uninstall setting saved.'=>'Αποθηκεύτηκε η ρύθμιση απεγκατάστασης.','unknown error'=>'άγνωστο σφάλμα','Unknown provider.'=>'Άγνωστος πάροχος.','Unknown search engine.'=>'Άγνωστη μηχανή αναζήτησης.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Σε αντίθεση με το hreflang — όπου το LF πάντα υπερισχύει άλλων πρόσθετων επειδή δεν μπορούν να γνωρίζουν τη πολυγλωσσική διαμόρφωσή σας — το Open Graph διαφέρει: τα πρόσθετα Yoast, Rank Math και παρόμοια ήδη παράγουν σωστά tags OG για το περιεχόμενό σας. Η διπλοεγγραφή τους δεν προσθέτει αξία. Σε αυτόματο mode, το LF ανιχνεύει ενεργά SEO plugins και προσθέτει μόνο ό,τι δεν μπορούν να παρέχουν: og:locale (τρέχουσα γλώσσα) και og:locale:alternate (όλες οι άλλες διαμορφωμένες γλώσσες).','Up'=>'Πάνω','Upload .mo file'=>'Ανέβασμα αρχείου .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Ανεβάστε συμπιεσμένα αρχεία .mo για να παρακάμψετε τις συμβολοσειρές πρόσθετου τρίτου μέρους για συγκεκριμένες τοπικές ρυθμίσεις — για παράδειγμα, μια προσαρμοσμένη μετάφραση VikBooking που χρησιμοποιεί "διαμέρισμα" αντί για "δωμάτιο". Τα αρχεία πρέπει να ακολουθούν τη συμβατική ονοματοδοσία του WordPress: {textdomain}-{locale}.mo (π.χ. vikbooking-ca.mo). Αποθηκεύονται στον φάκελο ανεβάσματος και επιβιώνουν από ενημερώσεις πρόσθετων.','Upload Override'=>'Ανέβασμα Παρακάμψεων','URL could not be mapped to a post — check the link target exists'=>'Ο σύνδεσμος URL δεν μπόρεσε να αντιστοιχιστεί σε ανάρτηση — ελέγξτε αν υπάρχει ο στόχος του συνδέσμου','URL structure'=>'Δομή URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Δομή URL: λειτουργία προθέματος διαδρομής (example.com/de/) που δεν απαιτεί αλλαγές στον διακομιστή. Λειτουργία υποτομέα (de.example.com) που απαιτεί μια εγγραφή wildcard DNS, ένα πιστοποιητικό SSL wildcard και μια αλλαγή στη διαμόρφωση του διακομιστή — δείτε τον οδηγό ρύθμισης διακομιστή.','URL to enter'=>'URL προς εισαγωγή','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Χρησιμοποιήστε εγγενή κοινή χρήση όταν είναι διαθέσιμη; αλλιώς αντιγράψτε στο clipboard. Συνιστώμενο προεπιλεγμένο για κουμπιά "Κοινή χρήση".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Χρησιμοποιήστε τις καρτέλες στην κορυφή αυτής της σελίδας για να διαμορφώσετε κάθε περιοχή. Οι αλλαγές στην καρτέλα δρομολογητή λαμβάνουν άμεσα effect; οι αλλαγές στα κλειδιά AI και τις ρυθμίσεις μοντέλου εφαρμόζονται στην επόμενη αίτηση AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Πίνακας ορολογίας που διαχειρίζεται ο χρήστης ανά ζεύγος γλωσσών. Οι καταχωρίσεις προστίθενται στην προτροπή συστήματος μετάφρασης, ώστε η ΤΝ να χρησιμοποιεί συνεπώς τους προτιμώμενους όρους — κρίσιμο για το λεξιλόγιο τομέα ("kWp", "PPA", "σημείο διασύνδεσης"), ονόματα εμπορικών σημάτων που δεν πρέπει να μεταφράζονται, και τυποποιημένη διατύπωση κανονισμών. Και τα δύο πεδία γλώσσας είναι προαιρετικά: αφήστε το "Πηγή γλώσσα" κενό για να εφαρμοστεί η καταχώριση ανεξάρτητα από τη γλώσσα από την οποία μεταφράζετε· αφήστε το "Στόχος γλώσσα" κενό για να το εφαρμόσετε σε όλες τις στοχευόμενες γλώσσες ταυτόχρονα.','Using custom meta description.'=>'Χρησιμοποιώντας προσαρμοσμένη μετα-περιγραφή.','Using LF AI meta description.'=>'Χρησιμοποιώντας μετα-περιγραφή AI του LF.','Value source'=>'Πηγή τιμής','View'=>'Προβολή','View built-in default'=>'Προβολή ενσωματωμένης προεπιλογής','View current robots.txt'=>'Προβολή τρέχοντος robots.txt','View details'=>'Προβολή λεπτομερειών','View Lingua Forge details'=>'Προβολή λεπτομερειών Lingua Forge','Visit plugin site'=>'Επισκεφθείτε τον ιστότοπο του πρόσθετου','Warning:'=>'Προειδοποίηση:','WebSite'=>'Ιστότοπος','WebSite — front page / blog index'=>'Ιστότοπος — αρχική σελίδα / ευρετήριο ιστολογίου','What LF provides — and collision avoidance'=>'Τι παρέχει το LF — και αποφυγή συγκρούσεων','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Τι παρέχει το LF: ετικέτες hreflang για κάθε διαμορφωμένη γλώσσα, ετικέτες Open Graph και Twitter Card με og:locale και og:locale:alternate, Schema.org JSON-LD με annotations inLanguage, και ένα ειδικό πολυγλωσσικό sitemap στο /lf-sitemap.xml με εναλλακτικές entries xhtml:link για όλες τις ομάδες μετάφρασης.','When another SEO plugin is installed'=>'Όταν εγκαθίσταται άλλο SEO plugin','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Όταν ενεργοποιείται η καταγραφή αποσφαλμάτωσης (μέσω του διακόπτη παρακάτω ή ορίζοντας το LINGUAFORGE_AI_DEBUG στο wp-config.php), οι λειτουργίες μετάφρασης και μετάφρασης προτύπων FSE γράφουν τις ακατέργαστες προτροπές AI και τις απαντήσεις τους στον δίσκο για αποσφαλμάτωση. Χρησιμοποιήστε αυτήν την ενότητα για να παρακολουθείτε αυτήν την έξοδο και να την διαγράψετε μόλις έχετε ό,τι χρειάζεστε — τα αρχεία μπορούν να αυξηθούν γρήγορα σε μεγάλες σελίδες. Διαμορφώστε τον προορισμό καταλόγου μέσω του φίλτρου linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Όταν ενεργοποιηθεί, οι επισκέπτες που επισκέπτονται για πρώτη φορά χωρίς cookie γλώσσας και χωρίς πρόθεμα γλώσσας στη διεύθυνση URL ανακατευθύνονται στην πιο κοντινή αντιστοιχισμένη έκδοση γλώσσας. Η ανακατεύθυνση παραλείπεται αν η προτιμώμενη γλώσσα του περιηγητή δεν είναι ανάμεσα στις ενεργές γλώσσες δρομολόγησης. Μόλις ένας επισκέπτης επιλέξει μια γλώσσα μέσω του διακόπτη, το cookie έχει προτεραιότητα και η κεφαλίδα του περιηγητή αγνοείται σε όλες τις μελλοντικές επισκέψεις.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Όταν ενεργοποιείται, το Lingua Forge παράγει τις ακόλουθες πρόσθετες μετα-ετικέτες στις σελίδες προϊόντων: og:type=product, og:price:amount, og:price:currency, og:availability, και τα αντίστοιχα namespace product που χρησιμοποιούνται από το Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Όταν ενεργοποιείται, το URL του sitemap ανακοινώνεται αυτόματα στο robots.txt και η προσωρινή μνήμη ανανεώνεται όταν αποθηκεύεται το μεταφρασμένο περιεχόμενο.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Όταν είναι ενεργά, τα SEO plugins όπως Yoast SEO, Rank Math, All in One SEO ή SEOPress, το Lingua Forge καταστέλλει αυτόματα την έξοδο hreflang τους μέσω φίλτρου. Τα γενικά SEO plugins παράγουν hreflang βάσει δομής URL με μία γλώσσα και δεν μπορούν να λάβουν υπόψη τη διαμόρφωση πολυγλωσσικής δρομολόγησης σας. Η έξοδος του LF είναι πάντα σωστή.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Ποιο επίπεδο μοντέλου να χρησιμοποιήσετε για μετάφραση ολόκληρης σελίδας. Η ποιότητα χρησιμοποιεί το μοντέλο που έχει διαμορφωθεί στον πίνακα Μοντέλων και προτείνεται για ακριβή, μακροσκελή μετάφραση. Μεταβείτε σε Ελαφρύ μόνο αν η ταχύτητα ή το κόστος είναι προτεραιότητα και το περιεχόμενο είναι σύντομο.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Ενώ είναι ενεργό, το πρόσθετο διαχειρίζεται το βασικό σετ OG και το LF εκπέμπει μόνο ετικέτες τοπικής γλώσσας (auto mode). Η αφαίρεσή του αλλάζει το LF σε πλήρη λειτουργία OG αυτόματα.','WooCommerce'=>'WooCommerce','WooCommerce product price'=>'Τιμή προϊόντος WooCommerce','WooCommerce SEO settings saved.'=>'Οι ρυθμίσεις SEO WooCommerce αποθηκεύτηκαν.','WooCommerce store currency'=>'Νόμισμα καταστήματος WooCommerce','Word count'=>'Αριθμός λέξεων','WP core canonical active (hreflang disabled)'=>'Το πυρήνα του WordPress ενεργοποιεί το canonical (hreflang απενεργοποιημένο)','WP-CLI reference'=>'Αναφορά WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Γράψτε προτροπές και απαντήσεις AI στον δίσκο για αποσφαλμάτωση','XML Sitemap'=>'XML Sitemap','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Μπορείτε επίσης να ορίσετε κλειδιά ως σταθερές ή μεταβλητές περιβάλλοντος (π.χ. στο wp-config.php). Αυτές οι πηγές χρησιμοποιούνται αυτόματα ως εφεδρική επιλογή όταν δεν αποθηκεύεται κλειδί βάσης δεδομένων.','You do not have permission to manage these settings.'=>'Δεν έχετε άδεια να διαχειριστείτε αυτές τις ρυθμίσεις.','You do not have permission to read this post.'=>'Δεν έχετε άδεια να διαβάσετε αυτήν την ανάρτηση.','{n} stale path(s)'=>'{n} παρωχημένη διαδρομή(ες)','~%d min read'=>'~%d λεπτά ανάγνωση' . "\0" . '~%d λεπτά ανάγνωση','— Any source language —'=>'— Οποιαδήποτε πηγή —','— Any target language —'=>'— Οποιαδήποτε στόχος —','— Any target —'=>'— Οποιαδήποτε στόχος —','— Any —'=>'— Οποιαδήποτε —','— auto-detect —'=>'— αυτόματη ανίχνευση —','— Deferred to plugin'=>'— Αναβλήθηκε σε plugin','— Disabled'=>'— Απενεργοποιήθηκε','— Not detected'=>'— Δεν ανιχνεύθηκε','— select a language —'=>'— επιλέξτε μια γλώσσα —','— toggle in Settings → Behavior.'=>'— εναλλαγή στις Ρυθμίσεις → Συμπεριφορά.','← Back'=>'← Πίσω','↑ Detected from current post'=>'↑ Ανιχνεύθηκε από την τρέχουσα ανάρτηση','→ Locale tags only (manual setting)'=>'→ Μόνο ετικέτες τοπικής ρύθμισης (χειροκίνητη ρύθμιση)','→ Locale tags only — deferring base OG to plugin'=>'→ Μόνο ετικέτες τοπικής ρύθμισης — αναβάλλοντας το βασικό OG στο πρόσθετο','↺ Re-translate'=>'↺ Επαναμετάφραση','↺ Refine'=>'↺ Βελτίωση','↺ Refresh'=>'↺ Ανανεώστε','↺ Refreshing…'=>'↺ Ανανεώνεται…','⚠ Borderline'=>'⚠ Οριακό','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Δεν βρέθηκαν αναρτήσεις <strong>{lang}</strong>. Βεβαιωθείτε ότι όλες οι μεταφρασμένες αναρτήσεις έχουν ορισμένο το μετα-περιεχόμενο Γλώσσα σε <strong>{lang}</strong> στο πλαίσιο μετα-γλώσσας.','⚠ No changes'=>'⚠ Χωρίς αλλαγές','⚠ No changes — re-scan?'=>'⚠ Χωρίς αλλαγές — επανεξέταση;','✅ Fixed ({n})'=>'✅ Διορθώθηκε ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Δεν βρέθηκαν σπασμένοι σύνδεσμοι ή ασυμβατότητες προτύπων για <strong>{lang}</strong>. Σάρωση <strong>{scanned}</strong> ανάρτησης(ων) και σελίδων — όλες οι έλεγχοι πέρασαν. Οι σύνδεσμοι τμημάτων προτύπου (κεφαλίδα, υποσέλιδο, πλαϊνή γραμμή) δεν περιλαμβάνονται εδώ — χρησιμοποιήστε το κουμπί Διόρθωση Τμημάτων Προτύπου για να ελέγξετε αυτά ξεχωριστά.','✅ Template fixed'=>'✅ Το πρότυπο διορθώθηκε','✓ %s notified successfully.'=>'✓ %s ειδοποιήθηκε με επιτυχία.','✓ Active'=>'✓ Ενεργό','✓ Active at /lf-sitemap.xml'=>'✓ Ενεργό στο /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Ενεργό — %d καταχώριση URL με εναλλακτικές γλώσσες' . "\0" . '✓ Ενεργό — %d καταχωρίσεις URL με εναλλακτικές γλώσσες','✓ Active — full OG + Twitter Cards'=>'✓ Ενεργό — πλήρες OG + Twitter Cards','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Ενεργό — ετικέτες τοπικής ρύθμισης (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Όλα τα μέρη δημιουργήθηκαν.','✓ All templates created.'=>'✓ Όλα τα πρότυπα δημιουργήθηκαν.','✓ All translated.'=>'✓ Όλες οι μεταφράσεις ολοκληρώθηκαν.','✓ Configured'=>'✓ Διαμορφωμένο','✓ Connection OK'=>'✓ Σύνδεση ΟΚ','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Το περιεχόμενο δημιουργήθηκε — δείτε την επικάλυψη για να ελέγξετε, να βελτιώσετε και να εφαρμόσετε.','✓ Done'=>'✓ Ολοκληρώθηκε','✓ Enabled'=>'✓ Ενεργό','✓ Good length'=>'✓ Καλή διάρκεια','✓ Hreflang active'=>'✓ Ενεργό Hreflang','✓ In safe storage'=>'✓ Σε ασφαλή αποθήκευση','✓ Language installed.'=>'✓ Η γλώσσα εγκαταστάθηκε.','✓ LF outputs'=>'✓ Εξόδοι LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Εξόδοι LF Άρθρο / WebPage / Ιστότοπος','✓ LF outputs full OG + Twitter Cards'=>'✓ Εξόδοι LF πλήρες OG + Twitter Cards','✓ LF outputs — plugin hreflang suppressed'=>'✓ Εξόδοι LF — πρόσθετο hreflang κατασταλμένο','✓ Links fixed.'=>'✓ Οι σύνδεσμοι διορθώθηκαν.','✓ Nav refs fixed.'=>'✓ Οι αναφορές πλοήγησης διορθώθηκαν.','✓ Parts fixed.'=>'✓ Τα μέρη διορθώθηκαν.','✓ Pattern translated.'=>'✓ Το μοτίβο μεταφράστηκε.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Βρίσκεται φυσικό αρχείο robots.txt. Η οδηγία Sitemap του LF είναι παρούσα.','✓ Refined — review the updated draft above.'=>'✓ Βελτιώθηκε — ελέγξτε το ενημερωμένο προσχέδιο παραπάνω.','✓ Translation saved'=>'✓ Μετάφραση αποθηκευμένη','✓ WP core canonical removed'=>'✓ Αφαιρέθηκε η κανόνα canonical του πυρήνα WP','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s αποτυχία ping. Η διεύθυνση URL του sitemap εξακολουθεί να ανακοινώνεται στο robots.txt — η μηχανή αναζήτησης θα το ανακαλύψει στην επόμενη ανίχνευσή της.','✗ Disabled'=>'✗ Απενεργό','✗ Error:'=>'✗ Σφάλμα:','✗ Failed:'=>'✗ Απέτυχε:','✗ Not configured'=>'✗ Μη διαμορφωμένο','✗ Too long'=>'✗ Πολύ μεγάλο','✗ Too short'=>'✗ Πολύ σύντομο','❌ Failed'=>'❌ Απέτυχε','📄 Wrong template'=>'📄 Λάθος πρότυπο','📍 Stale path (page moved)'=>'📍 Παλαιά διαδρομή (η σελίδα μετακινήθηκε)']];
